import {setup as setupCommunity,route as communityRoute,action as communityAction} from '/community.mjs';
import {NEED_FIELDS,ELIGIBILITY,IMPACT,EXECUTION,money,kobo} from '/core/model.mjs';
const root=document.getElementById('root'),modal=document.getElementById('modal');
let currentUser=null,detail=null,activeTab='overview',toastTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Date(v).toLocaleDateString('en-NG',{day:'numeric',month:'short',year:'numeric'}):'Not recorded';
const badge=(label,type='')=>`<span class="badge ${type}">${esc(label)}</span>`;
const link=(url,label,style='button-secondary')=>`<a class="${style}" href="${url}">${label}</a>`;
const button=(action,label,extra='',style='button-secondary small')=>`<button class="${style}" data-action="${action}" ${extra}>${label}</button>`;
const preview=location.hostname==='127.0.0.1'||location.hostname==='localhost';
const brand=`<a class="brand" href="/"><img src="/logo.png" alt="CivicBench"/></a>`;
function header(){return `${preview?'<div class="preview-banner">Local development preview · no production records or payments are changed</div>':''}<header class="site-header"><div class="wrap nav">${brand}<nav class="nav-links" aria-label="Main navigation"><a href="/projects">Projects</a><a href="/approach" class="optional">How it works</a><a href="/app/propose" class="optional">Propose a need</a><a href="/app" class="button-secondary">Workspace <span aria-hidden="true">↗</span></a></nav></div></header>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top">${brand}<nav class="footer-links" aria-label="Footer"><a href="/approach">Our approach</a><a href="/roadmap">Pilot & launch plan</a><a href="/projects">Public records</a><a href="/credentials">Verify a contribution</a><a href="/credits">Photo credits</a></nav></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} CivicBench · Public needs. Verified action.</span><span>Reviewed needs. Verified contributions.</span></div></div></footer>`;}
function page(html){root.innerHTML=header()+`<main id="main">${html}</main>`+footer();}
function notice(message,type=''){return `<div class="notice ${type}">${message}</div>`;}
function empty(title,description){return `<div class="empty"><h3>${title}</h3><p>${description}</p></div>`;}
function toast(message){document.getElementById('toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast').textContent='',5500);}
async function api(path,body,options={}){const token=sessionStorage.getItem('cb_session');const response=await fetch('/api/v2'+path,{method:body?'POST':'GET',...options,headers:{...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{}),...options.headers},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json().catch(()=>({error:'The server returned an unexpected response.'}));if(!response.ok)throw new Error(data.error||'Request failed.');return data;}
const steps=[['Point out a need','Describe a public-good problem and the change that would matter.'],['Screen & structure','Check eligibility, name a steward, and turn the need into bounded tasks.'],['Mobilise resources','Bring money, materials, volunteers, or a mix. Funding is optional.'],['Contribute','Agree to paid or volunteer terms, do the work, and submit evidence.'],['Review independently','Vetted reviewers check the proof against an agreed, versioned rubric.'],['Credential, pay & share','Record verified contributions, pay accepted funded work, and follow through.']];
async function home(){page('<div class="wrap"><section class="hero"><div><div class="eyebrow"><span class="dot"></span>For our communities</div><h1>See a need.<br><em>Make a difference.</em></h1><p class="lead">Bring a community need. Put your skills to work. Help a project move forward.</p><div class="actions">'+link('/app/propose','Propose a need ↗','button')+link('/projects','Explore projects →')+'</div><div class="chips"><span class="badge">Individuals</span><span class="badge blue">Organisations</span><span class="badge">Paid & volunteer work</span></div></div><div class="hero-visual"><figure class="hero-photo"><img src="/images/community-volunteers.webp" alt="Lagos Food Bank volunteers carrying food boxes" fetchpriority="high" width="1200" height="800"><figcaption>Lagos, Nigeria · Contextual photograph</figcaption></figure><div class="photo-note"><span class="check">✓</span><div><strong>Every contribution counts.</strong><small>Reviewed work. A record you can share.</small></div></div></div></section><section class="section" style="padding-top:0"><div class="section-head"><h2>Where will you start?</h2></div><div class="cards"><a class="card card-link" href="/app/propose"><div class="step-number">01 /</div><h3>Bring a need</h3><p>Tell us what needs to change and who it would help.</p><span class="tile-label">Propose a need ↗</span></a><a class="card card-link" href="/projects"><div class="step-number">02 /</div><h3>Contribute your skills</h3><p>Find clear tasks with agreed paid or volunteer terms.</p><span class="tile-label">Explore projects ↗</span></a><a class="card card-link" href="/app/organisation"><div class="step-number">03 /</div><h3>Support the work</h3><p>Bring funding, materials, or your organisation’s team.</p><span class="tile-label">Organisation workspace ↗</span></a></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Projects</div><h2>Follow the work.</h2></div>'+link('/projects','See all projects →')+'</div><div id="home-projects">'+empty('The first projects are on their way.','Have a need in mind? Propose it for review.')+'</div></section><section class="section"><div class="two-col"><div class="card"><div class="eyebrow">Your contribution story</div><h2>Work you can point to.</h2><p>Build a Civic CV from your verified contributions. Share a single piece of work or create your Impact Recap.</p>'+link('/app/cv','My Civic CV →','button')+'</div><div class="card recap-teaser"><span class="badge">For people & organisations</span><h2 style="margin-top:24px">Your year.<br>Your contribution.</h2><p>A shareable recap of the work you did and the projects you supported.</p>'+link('/app/recap','Create your recap →','button-secondary')+'</div></div></section><section class="section"><div class="section-head"><h2>A clear way forward.</h2></div><div class="simple-flow"><span>Propose</span><b>→</b><span>Review & structure</span><b>→</b><span>Fund or contribute</span><b>→</b><span>Verify</span><b>→</b><span>Record & share</span></div><p class="hero-note">Proposals are reviewed before publication. Work is independently checked before a contribution record is issued.</p></section></div>');try{const {projects}=await api('/public/projects');if(projects.length)document.getElementById('home-projects').innerHTML=projectCards(projects.slice(0,3))}catch{}}

function projectCards(projects){return `<div class="cards">${projects.map(p=>`<a class="card card-link" href="/projects/${esc(p.id)}"><div class="label-line">${badge(p.execution_status)}${badge(p.impact_status,p.impact_status==='resolved'?'':'amber')}</div><h3>${esc(p.title)}</h3><p>${esc(p.outcome)}</p><div class="metadata"><span>${esc(p.audience)}</span><span>Target ${fmt(p.target_date)}</span></div><div class="tile-label">View completion & impact ↗</div></a>`).join('')}</div>`;}
async function projects(){page(`<div class="wrap"><div class="page-hero"><div class="eyebrow">Public project records</div><h1>What happened.<br>What remains.</h1><p>Every project has a steward, a target date, and a record of both completion and impact. Records below are published only after screening and moderation.</p></div><div class="filter-bar"><input class="search" id="project-search" aria-label="Search projects" placeholder="Search a need, audience, or outcome…"/><div class="field" style="margin:0"><select id="project-filter" aria-label="Filter execution status"><option value="">All stages</option>${EXECUTION.filter(s=>!['proposed','screening','rejected'].includes(s)).map(s=>`<option>${s}</option>`).join('')}</select></div></div><div id="project-list" class="section" style="padding-top:0">${empty('No approved project records yet.','Propose a need to help start the next project.')}</div></div>`);try{const {projects}=await api('/public/projects');const update=()=>{const q=document.getElementById('project-search').value.toLowerCase(),stage=document.getElementById('project-filter').value;const filtered=projects.filter(p=>(!stage||p.execution_status===stage)&&`${p.title} ${p.audience} ${p.outcome}`.toLowerCase().includes(q));document.getElementById('project-list').innerHTML=filtered.length?projectCards(filtered):empty(projects.length?'No projects match your search.':'No approved project records yet.','Try another search or return as the first pilot results are published.');};document.getElementById('project-search').addEventListener('input',update);document.getElementById('project-filter').addEventListener('change',update);update();}catch(e){document.getElementById('project-list').innerHTML=notice(esc(e.message),'error');}}
function record(label,value){return `<div class="record-row"><dt>${label}</dt><dd>${esc(value||'Not yet recorded')}</dd></div>`;}
async function publicProject(pid){page('<div class="wrap loading">Loading project record…</div>');try{const {project:p,corrections}=await api('/public/projects/'+encodeURIComponent(pid));page(`<div class="wrap section"><div class="breadcrumbs"><a href="/projects">Projects</a> / Public record</div><div class="eyebrow">${esc(p.audience)}</div><h1 style="font-size:3rem">${esc(p.title)}</h1><p class="lead">${esc(p.public_summary)}</p><div class="status-row">${badge('Execution: '+p.execution_status)}${badge('Impact: '+p.impact_status,'amber')}</div><div class="metadata"><span>Steward: ${esc(p.steward)}</span><span>Target: ${fmt(p.target_date)}</span><span>Updated: ${fmt(p.updated_at)}</span></div><div class="actions spacer">${['structured','active'].includes(p.execution_status)?button('project-interest','I can help →','data-id="'+p.id+'"','button'):''}</div><div class="two-col spacer"><div class="card"><div class="eyebrow">The work</div><h2 style="font-size:1.6rem">Completion record</h2><dl>${record('Desired public outcome',p.outcome)}${record('Verified deliverables',p.completion_record)}${record('How the result was shared',p.dissemination_record)}</dl></div><div class="card"><div class="eyebrow">The change</div><h2 style="font-size:1.6rem">Impact & outstanding need</h2><dl>${record('Impact evidence',p.impact_evidence)}${record('What still needs to happen',p.outstanding_need)}${record('Next follow-up',fmt(p.next_impact_review_date))}${record('Closing rule',p.closing_rule)}</dl></div></div><section class="spacer"><h3>Corrections & follow-through</h3>${corrections.length?corrections.map(c=>`<div class="item"><small>${fmt(c.corrected_at)}</small><p>${esc(c.summary)}</p></div>`).join(''): '<p class="muted">No corrections recorded. To flag an issue, contact the named project steward through your CivicBench coordinator.</p>'}</section></div>`);}catch(e){page(`<div class="wrap section">${notice(esc(e.message),'error')}${link('/projects','Back to projects')}</div>`);}}
function approach(){page(`<div class="wrap section prose"><div class="eyebrow">Our approach</div><h1 style="font-size:3.1rem">Need first.<br>Verification always.</h1><p>CivicBench turns public-good needs into structured projects and bounded tasks. A project can bring together money, materials, and volunteer time. It always needs independent verification.</p><h2>Three separate records</h2><div class="cards"><div class="card"><div class="tile-label">01 / Need or project</div><p>The problem, desired outcome, steward, milestones, and records of completion and impact.</p></div><div class="card"><div class="tile-label">02 / Funding</div><p>Money or material commitments, task allocations, and actual payment or delivery records.</p></div><div class="card"><div class="tile-label">03 / Task</div><p>A bounded brief, agreed terms, versioned rubric, evidence standard, contributors, and review.</p></div></div><h2>Screening is the first trust test.</h2><p>We start with needs curated by CivicBench or its partners. Before a need becomes a project, it must pass public benefit, lawful authority, privacy and consent, contributor safety, clear deliverables, and independent verification checks.</p><h3>The minimum need record</h3><ol class="mini-list">${NEED_FIELDS.map(([,label])=>`<li>${label}</li>`).join('')}</ol><p>Incomplete proposals return for clarification. A rejected need keeps its reason and is terminal; a revised proposal becomes a new linked record. Every published project also has a rule for re-planning or closing stalled work.</p><h2>The same verification for paid and volunteer work.</h2><p>Every contributor agrees to paid or volunteer terms before starting. A vetted reviewer applies the agreed rubric and declares conflicts. Nobody reviews work they performed or a project they fund. Accuracy comes before ratings.</p><p>After independent approval, the funder has 72 hours to contest funded work on rubric grounds. The steward has the same window for unfunded work. Every accepted contribution earns a verifiable record; volunteers receive the same verified credit.</p><h2>Funding is a resource, not the starting point.</h2><p>Paid assignments need committed funding before they open. Payments use a licensed arrangement or written manual agreement. CivicBench records payments; an internal balance is not escrow. Public pooled sponsorship stays closed until legal advice, payment arrangements, and refund rules are in place.</p><h2>Completion is not impact.</h2><p>A delivered report can be a completed project while the underlying problem remains unresolved. We record completion, impact evidence, outstanding needs, and the next follow-up date separately. Only reviewed and accepted results are shared, with privacy checked first.</p><h2>True costs are part of the record.</h2><p>Screening, coordination, expert review, and credential verification take time even when donated. The pilots track time at a stated shadow rate, direct expenses, and cost per verified contribution. Repeat funding remains the economic test.</p>${link('/roadmap','See the pilot and launch plan →','button')}</div>`);}
function roadmap(){const timeline=[['By 18 Oct 2026','Prepare the intake','Choose the curated need and its steward. Define the screening form, recruit two reviewers, agree a shadow rate, and start five funder conversations.'],['19 Oct – 8 Nov','Pilot A · unfunded need','One need, 10–20 bounded tasks, 5–10 volunteer contributors, and two reviewers. Test coordination, verification, credentials, and true costs.'],['9 Nov 2026','Gate 1 · Pilot A review','Review delivery, quality, credentials, costs, and the three-object schema. A committed funder is needed for Pilot B.'],['9 Nov – 6 Dec','Pilot B · funded need','Repeat the work with committed funding, explicit assignment terms, agreed payments, and a test of willingness to fund more.'],['7 Dec 2026','Gate 2 · both pilots','Confirm accepted work, actual contributor payments, cost per usable output, and a concrete repeat funding commitment before core development.'],['After Gate 2','Core build & controlled testing','Build the tested workflow. Complete 3–5 further curated projects with public completion, impact, and outstanding-need records.'],['8 Mar 2027','Gate 3 · service readiness','Review end-to-end operation, credentials, security, payments, moderation, quality, and true costs.'],['22 Mar 2027','Proposed controlled launch','Conditional on Gate 3. A missed gate moves the dates that follow. Wider participation does not open on a calendar date.']];page(`<div class="wrap section"><div class="eyebrow">Two pilots · three gates</div><h1 style="font-size:3rem">Evidence before expansion.</h1><p class="muted prose">The first service is curated and supervised. Each gate leads to a decision: proceed, fix the weak point and retest, or redesign.</p>${notice('These are proposed dates from the canonical build plan. No pilot, gate, or launch is marked complete without recorded evidence.')}<div class="prose">${timeline.map(([when,title,copy])=>`<article class="timeline"><time>${when}</time><div><h3>${title}</h3><p>${copy}</p></div></article>`).join('')}</div><section class="section"><h2>Open only when ready.</h2><div class="cards">${[['Public need submission','Proven moderation, measured screening time, and a working closing rule.'],['Contributor self-selection','Review capacity within 48 hours, with fraud and duplicate checks.'],['Field work','Task-specific safety and data protection rules, plus legal advice.'],['Pooled sponsorship','Licensed payments, refund rules, and legal advice.'],['Self-serve funder tools','Templates that work across repeat projects.'],['Open request board','Moderation proven on public submissions.']].map(([title,copy])=>`<div class="card">${badge('Condition-dependent','gray')}<h3>${title}</h3><p>${copy}</p></div>`).join('')}</div></section></div>`);}
async function credential(cid){if(!cid){page(`<div class="wrap section prose"><div class="eyebrow">Verified contribution records</div><h1 style="font-size:3rem">Recognition backed by review.</h1><p>Each accepted contribution has a unique verification ID. Paid and volunteer work use the same standard. Contributors choose whether their record is public.</p><form id="verify-form"><div class="field"><label for="verification-id">Verification ID</label><input id="verification-id" required placeholder="Enter the full verification ID"/></div><button class="button">Verify a record →</button></form><p class="hero-note">A credential verifies a contribution. It does not claim the underlying public need has been solved.</p></div>`);document.getElementById('verify-form').addEventListener('submit',e=>{e.preventDefault();location.href='/credentials/'+encodeURIComponent(document.getElementById('verification-id').value.trim());});return;}page('<div class="wrap loading">Checking verification record…</div>');try{const {credential:c}=await api('/public/credentials/'+encodeURIComponent(cid)+(new URLSearchParams(location.search).get('share')?'?share='+encodeURIComponent(new URLSearchParams(location.search).get('share')):''));page(`<div class="wrap section prose"><div class="eyebrow">Public verification record</div><h1 style="font-size:2.7rem">${c.correction_status==='revoked'?'Credential withdrawn.':'A verified contribution.'}</h1>${badge(c.correction_status,c.correction_status==='revoked'?'red':'')}<dl>${record('Project',c.project_title)}${record('Task',c.task_title)}${record('Independent verification',c.decision)}${record('Issued',fmt(c.issued_at))}${c.correction_reason?record('Correction record',c.correction_reason):''}</dl><p class="credential-id">${esc(c.id)}</p><p class="hero-note">This record confirms reviewed work. It does not establish that the project’s wider need is resolved. Contributor identity and private evidence are not disclosed here.</p></div>`);}catch(e){page(`<div class="wrap section prose"><h1 style="font-size:2.4rem">Record unavailable.</h1><p class="muted">The ID may be incorrect, or the contributor may have kept this credential private.</p>${link('/credentials','Check another record')}</div>`);}}
function input(name,label,type='text',required=true,help='',value=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" ${required?'required':''} value="${esc(value)}" ${type==='number'?'min="0" step="1"':''}/>${help?`<small>${help}</small>`:''}</div>`;}
function area(name,label,help='',value='',required=true){return `<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" ${required?'required':''} maxlength="6000">${esc(value)}</textarea>${help?`<small>${help}</small>`:''}</div>`;}
function select(name,label,values,value=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${values.map(v=>`<option value="${esc(typeof v==='string'?v:v[0])}" ${(typeof v==='string'?v:v[0])===value?'selected':''}>${esc(typeof v==='string'?v:v[1])}</option>`).join('')}</select></div>`;}
function check(name,label){return `<label class="checkbox-field"><input name="${name}" type="checkbox" required/><span>${label}</span></label>`;}
function openForm(title,intro,fields,submitLabel,submit){modal.innerHTML=`<button class="modal-close" aria-label="Close dialog" data-action="close-modal">×</button><h2>${title}</h2><p class="modal-intro">${intro}</p><form id="modal-form"><div class="form-grid">${fields}</div><div class="form-error" id="form-error" role="alert"></div><div class="form-actions">${button('close-modal','Cancel','','button-secondary')}<button class="button" type="submit">${submitLabel}</button></div></form>`;modal.showModal();document.getElementById('modal-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget;const data=Object.fromEntries(new FormData(f));for(const el of f.querySelectorAll('input[type=checkbox]'))data[el.name]=el.checked;const submitButton=f.querySelector('button[type=submit]');submitButton.disabled=true;document.getElementById('form-error').textContent='';try{await submit(data,f);modal.close();toast('Record saved.');await route();}catch(err){document.getElementById('form-error').textContent=err.message;}finally{submitButton.disabled=false;}});}
function workspace(html,section='dashboard'){root.innerHTML=header()+`<div class="workspace"><aside class="sidebar"><div class="sidebar-label">My workspace</div>${[['dashboard','/app','Overview'],['proposals','/app/proposals','My proposals'],['cv','/app/cv','Civic CV'],['recap','/app/recap','Impact Recap'],['organisation','/app/organisation','Organisation'],['projects','/app/projects','Needs & projects'],['contributions','/app/contributions','My contributions'],['review','/app/review','Review queue'],['credentials','/app/credentials','Credentials'],['gates','/app/gates','Pilot evidence'],...(currentUser.roles.includes('coordinator')?[['admin','/app/admin','Admin review queue'],['activity','/app/activity','Activity history']]:[])].map(([s,url,label])=>`<a href="${url}" class="${s===section?'active':''}">${label}</a>`).join('')}<div class="user">${esc(currentUser.name)}<br><small>${esc(currentUser.roles.join(', ')||'Awaiting assignment')}</small><br>${button('logout','Sign out','','button-secondary small')}</div></aside><main class="workspace-main" id="main">${html}</main></div>`;}
async function register(){page('<div class="wrap"><div class="auth-page">'+brand+'<h1>Create your account.</h1><form id="register-form">'+input('name','Your name')+input('email','Email','email')+input('password','Password','password',true,'At least 10 characters.')+'<div class="form-error" role="alert"></div><button class="button" disabled>Checking connection…</button></form><p class="hero-note">'+link('/app/login','Already have an account? Sign in','')+'</p></div></div>');document.getElementById('register-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{const response=await fetch('/api/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const result=await response.json();if(!response.ok)throw new Error(result.error||'Account creation failed.');if(result.token){sessionStorage.setItem('cb_session',result.token);location.href='/app'}else location.href='/app/login'}catch(err){f.querySelector('.form-error').textContent=err.message;b.disabled=false}};const button=document.querySelector('#register-form button');try{const response=await fetch('/api/account-status');const result=await response.json();if(!response.ok||!result.ready)throw new Error('Account creation is temporarily unavailable. Please try again shortly.');button.disabled=false;button.textContent='Create account →'}catch(err){document.querySelector('#register-form .form-error').textContent=err.message;button.textContent='Create account →'}}
async function login(){page(`<div class="wrap"><div class="auth-page">${brand}<div class="eyebrow">Your CivicBench account</div><h1>Welcome back.</h1><p class="muted">Your projects, contributions and records.</p><p>${link('/app/register','Create an account →','')}</p><form id="login-form">${input('email','Email','email')}${input('password','Password','password')}<div class="form-error" id="login-error" role="alert"></div><button class="button" style="width:100%">Sign in →</button></form>${preview?`<p class="hero-note">For local QA only, choose a simulated role. This does not sign into production.</p><div class="actions">${button('local-login','Coordinator','data-role="coordinator"')}${button('local-login','Contributor','data-role="contributor"')}${button('local-login','Reviewer','data-role="reviewer"')}</div>`:''}</div></div>`);document.getElementById('login-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{const response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const data=await response.json();if(!response.ok)throw new Error(data.error||'Sign-in failed.');sessionStorage.setItem('cb_session',data.token);location.href=sessionStorage.getItem('cb_after_login')||'/app';sessionStorage.removeItem('cb_after_login');}catch(err){document.getElementById('login-error').textContent=err.message;}finally{b.disabled=false;}});}
async function ensureUser(){try{({user:currentUser}=await api('/me'));return true;}catch(e){page(`<div class="wrap section prose"><h1 style="font-size:2.5rem">Workspace being prepared.</h1>${notice(esc(e.message),'blue')}<p class="muted">Please sign in to use your workspace.</p><div class="actions">${link('/app/login','Sign in')}${link('/','Back to CivicBench')}</div></div>`);return false;}}
async function dashboard(section){const {projects}=await api('/projects');const staff=currentUser.roles.includes('coordinator');if(section==='projects'){workspace(`<div class="section-head"><div><div class="eyebrow">Needs & projects</div><h1>Needs & projects</h1><p class="muted">Screen before structuring. Track completion and impact separately.</p></div>${staff?button('new-need','Create a need','','button'):''}</div>${projectTable(projects)}`,'projects');return;}let verified=0,funded=0;for(const p of projects){const d=await api('/projects/'+p.id);verified+=d.credentials.filter(c=>c.correction_status!=='revoked').length;funded+=d.funding.filter(f=>f.type==='money'&&['committed','held','released'].includes(f.status)).reduce((s,f)=>s+f.amount_kobo,0);}workspace(`<div class="section-head"><div><div class="eyebrow">Your CivicBench workspace</div><h1>From need to verified action.</h1><p class="muted">A clear record of the work, the resources, and what remains.</p></div>${link('/app/propose','＋ Propose a need','button')}</div><div class="stats"><div class="stat"><small>Needs in your workspace</small><strong>${projects.length}</strong></div><div class="stat"><small>Structured or active projects</small><strong>${projects.filter(p=>['structured','active'].includes(p.execution_status)).length}</strong></div><div class="stat"><small>Verified contribution records</small><strong>${verified}</strong></div><div class="stat"><small>Money committed or released</small><strong style="font-size:1.5rem">${money(funded)}</strong></div></div>${notice('Read and accept your task terms before starting.','blue')}<div class="section-head"><h3>Your projects</h3>${link('/app/projects','View all →','')}</div>${projectTable(projects)}${staff?`<div class="spacer actions">${button('grant-role','Assign an existing account a role')}${link('/app/gates','Review pilot gates')}</div>`:''}`);}
function projectTable(projects){return projects.length?`<div class="table-wrap"><table><thead><tr><th>Need / project</th><th>Execution</th><th>Impact</th><th>Steward & target</th></tr></thead><tbody>${projects.map(p=>`<tr><td><a href="/app/projects/${p.id}">${esc(p.title)}</a><small>${esc(p.audience)}</small></td><td>${badge(p.execution_status)}</td><td>${badge(p.impact_status,'amber')}</td><td>${esc(p.steward)}<small>${fmt(p.target_date)}</small></td></tr>`).join('')}</tbody></table></div>`:empty('Start with one clear need.','Create the complete 12-item record, name a steward, and screen eligibility before any task or funding goes live.');}
async function privateProject(pid){detail=await api('/projects/'+pid);const {project:p,manager}=detail;const tabs=['overview','tasks','contributions',...(manager||currentUser.roles.includes('funder')?['resources']:[]),...(manager?['costs','decisions']:[])];if(!tabs.includes(activeTab))activeTab='overview';workspace(`<div class="breadcrumbs"><a href="/app/projects">Needs & projects</a> / Project record</div><div class="section-head"><div><div class="eyebrow">${esc(p.audience)}</div><h1>${esc(p.title)}</h1><div class="metadata"><span>Steward: ${esc(p.steward)}</span><span>Target ${fmt(p.target_date)}</span>${p.previous_id?`<span>Resubmission of <a href="/app/projects/${esc(p.previous_id)}">a rejected need</a></span>`:''}</div></div><div class="actions">${badge(p.execution_status)}${badge(p.impact_status,'amber')}</div></div><div class="pill-tabs" role="tablist">${tabs.map(tab=>`<button role="tab" aria-selected="${activeTab===tab}" class="${activeTab===tab?'active':''}" data-action="tab" data-tab="${tab}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div id="project-panel">${projectPanel()}</div>`,'projects');}
function projectPanel(){const d=detail,p=d.project,manager=d.manager,staff=currentUser.roles.includes('coordinator');
 if(activeTab==='overview')return `<div class="two-col"><div class="card"><div class="eyebrow">The need record</div><dl>${NEED_FIELDS.map(([key,label])=>record(label,p[key==='targetDate'?'target_date':key])).join('')}${record('Closing rule',p.closing_rule)}</dl></div><div class="stack"><div class="card"><div class="eyebrow">Completion & impact</div><dl>${record('Verified completion',p.completion_record)}${record('Impact evidence',p.impact_evidence)}${record('Outstanding need',p.outstanding_need)}${record('Next review',fmt(p.next_impact_review_date))}${record('Shared with beneficiaries',p.dissemination_record)}</dl>${manager?button('outcome','Update outcome record'):''}</div><div class="card"><h3>Screening & publication</h3><p>A screened need can be published with a moderated summary. Verified results require independent review and the acceptance window.</p><div class="actions">${staff&&['proposed','screening'].includes(p.execution_status)?button('screen','Screen this need'):''}${staff&&['structured','active','completed','closed'].includes(p.execution_status)?button('publish',p.published?'Update public summary':'Publish moderated record'):''}${staff&&p.execution_status==='rejected'?button('new-need','Resubmit as a linked need','data-previous="'+p.id+'"'):''}${staff&&p.published?button('correction','Record a public correction'):''}</div></div></div></div>`;
 if(activeTab==='tasks')return `<div class="section-head"><div><h3>Bounded work</h3><p class="muted">Rubric, evidence, and paid or volunteer terms are fixed before assignment.</p></div>${manager&&['structured','active'].includes(p.execution_status)?button('new-task','Create task','','button'):''}</div><div class="stack">${d.tasks.length?d.tasks.map(taskCard).join(''):empty('No tasks yet.','Screen and structure the need, then create bounded tasks with explicit terms.')}</div>`;
 if(activeTab==='contributions')return `<div class="stack">${d.contributions.length?d.contributions.map(contributionCard).join(''):empty('No evidence submitted yet.','Contributors submit work and stored proof after accepting their assigned terms.')}</div>`;
 if(activeTab==='resources')return `<div class="section-head"><div><h3>Funding & materials</h3><p class="muted">Commitments belong to the project. Paid tasks need a confirmed allocation.</p></div>${manager?button('funding','Record a commitment','','button'):''}</div>${notice('These are records of agreed external funding or material delivery. CivicBench does not collect pooled funds or provide escrow.','blue')}<div class="stack">${d.funding.length?d.funding.map(f=>`<div class="item"><div class="label-line">${badge(f.type)}${badge(f.status)}</div><h3>${esc(f.funder_name)} · ${f.type==='money'?money(f.amount_kobo):`${f.quantity} ${esc(f.unit)} of ${esc(f.material_description)}`}</h3><dl>${record('Agreement',f.agreement_ref)}${record('Payment / delivery route',f.payment_route)}${record('Delivery record',f.delivery_record)}${record('Funding ID (for task allocation)',f.id)}</dl></div>`).join(''):empty('Resources start with an agreement.','Record money or material commitments here; volunteer tasks can proceed without them.')}</div>`;
 if(activeTab==='costs'){const total=d.costs.reduce((sum,c)=>sum+c.direct_kobo+Math.round(c.minutes*c.rate_kobo/60),0),count=d.credentials.filter(c=>c.correction_status!=='revoked').length;return `<div class="section-head"><h3>The true cost of the work</h3>${button('cost','Record time or expense','','button')}</div><div class="stats"><div class="stat"><small>Total recorded cost</small><strong>${money(total)}</strong></div><div class="stat"><small>Cost per verified contribution</small><strong>${count?money(Math.round(total/count)):'—'}</strong></div></div>${notice('Donated time is valued at the recorded shadow rate. It is a cost estimate, not a payment liability.','blue')}<div class="table-wrap"><table><thead><tr><th>Category</th><th>Time</th><th>Rate / hour</th><th>Direct cost</th><th>Basis</th></tr></thead><tbody>${d.costs.map(c=>`<tr><td>${esc(c.category)}<small>${esc(c.note)}</small></td><td>${c.minutes} min</td><td>${money(c.rate_kobo)}</td><td>${money(c.direct_kobo)}</td><td>${c.donated?'Donated':'Paid'}</td></tr>`).join('')}</tbody></table></div>`;}
 if(activeTab==='decisions')return `<h3>Screening decision log</h3><div class="stack">${d.decisions.map(item=>`<div class="item">${badge(item.decision)}<small> · ${fmt(item.created_at)}</small><p>${esc(item.reason)}</p><p class="muted">Recorded by account ${esc(item.actor_id)}</p></div>`).join('')||empty('No screening decisions yet.','Every decision and its reason will be kept with this project.')}<h3>Public corrections</h3>${d.corrections.map(c=>`<div class="item"><p>${esc(c.summary)}</p><small>${fmt(c.corrected_at)}</small></div>`).join('')}</div>`;return '';}
function taskCard(t){const assignments=detail.assignments.filter(a=>a.task_id===t.id),mine=assignments.find(a=>a.contributor_id===currentUser.id);return `<article class="item"><div class="label-line"><div>${badge(t.mode,t.mode==='paid'?'blue':'')}${badge(t.status,'gray')}</div><small>Due ${fmt(t.deadline)}</small></div><h3>${esc(t.title)}</h3><pre>${esc(t.brief)}</pre><div class="metadata"><span>${t.mode==='paid'?money(t.reward_kobo)+' per contributor':'Volunteer · no implied payment'}</span><span>${t.capacity} contributor slot${t.capacity>1?'s':''}</span><span>${t.reviews_required} independent review${t.reviews_required>1?'s':''}</span></div><details><summary>Agreed rubric, evidence & terms</summary><dl>${record('Rubric v'+t.rubric_version,t.rubric)}${record('Evidence standard',t.evidence_standard)}${record('Assignment terms',t.terms)}${record('Steward sign-off',t.steward_signoff)}${t.mode==='paid'?record('Funder sign-off',t.funder_signoff):''}</dl></details><div class="actions">${detail.manager&&t.status==='draft'&&t.mode==='paid'?button('allocate','Allocate committed funding',`data-id="${t.id}"`):''}${detail.manager&&t.status==='draft'?button('open-task','Open for supervised assignment',`data-id="${t.id}"`):''}${detail.manager&&['open','claimed'].includes(t.status)?button('assign','Assign contributor',`data-id="${t.id}"`):''}${mine&&!mine.agreed_at?button('agree','Read & agree to terms',`data-id="${t.id}"`,'button small'):''}${mine?.agreed_at&&!['accepted','closed'].includes(t.status)?button('submit','Submit evidence',`data-id="${t.id}"`,'button small'):''}</div>${assignments.length?`<p class="hero-note">Assignments: ${assignments.map(a=>`${esc(a.contributor_id)} · ${a.agreed_at?'terms accepted':'awaiting agreement'}`).join(' / ')}</p>`:''}</article>`;}
function contributionCard(c){const t=detail.tasks.find(t=>t.id===c.task_id),reviews=detail.reviews.filter(r=>r.contribution_id===c.id),proof=detail.evidence.filter(e=>e.contribution_id===c.id),assigned=detail.reviewAssignments.some(a=>a.contribution_id===c.id&&a.reviewer_id===currentUser.id),reviewed=reviews.some(r=>r.reviewer_id===currentUser.id);return `<article class="item"><div class="label-line">${badge(c.status,c.status==='accepted'?'':c.status==='rejected'?'red':'amber')}<small>${fmt(c.submitted_at)}</small></div><h3>${esc(t?.title)}</h3><p>Contributor account ${esc(c.contributor_id)}</p><pre>${esc(c.submission)}</pre><div class="metadata"><span>${proof.length} stored evidence file${proof.length===1?'':'s'}</span>${c.acceptance_due?`<span>Acceptance window ends ${new Date(c.acceptance_due).toLocaleString('en-NG')}</span>`:''}</div><div class="actions">${proof.map(e=>button('download-evidence',esc(e.filename),`data-id="${e.id}"`)).join('')}${c.contributor_id===currentUser.id&&['submitted','rejected'].includes(c.status)?button('upload-evidence','Upload proof file',`data-id="${c.id}"`):''}${detail.manager&&['submitted','under review'].includes(c.status)?button('assign-reviewer','Assign vetted reviewer',`data-id="${c.id}"`):''}${assigned&&!reviewed&&c.status==='under review'?button('review','Review against rubric',`data-id="${c.id}"`,'button small'):''}${detail.manager&&c.status==='acceptance'?button('finalize','Finalise after acceptance window',`data-id="${c.id}"`):''}${['rejected','acceptance'].includes(c.status)&&(c.contributor_id===currentUser.id||t?.acceptance_by===currentUser.id)?button('dispute','Contest on rubric grounds',`data-id="${c.id}"`):''}${detail.manager&&c.status==='disputed'?button('resolve-dispute','Record panel decision',`data-id="${c.id}"`):''}${currentUser.roles.includes('coordinator')&&c.status==='accepted'&&t?.mode==='paid'&&!detail.payments.some(p=>p.contribution_id===c.id)?button('payment','Record an external payment',`data-id="${c.id}"`):''}</div>${reviews.length?`<details class="spacer"><summary>Independent review records (${reviews.length})</summary>${reviews.map(r=>`<dl>${record('Decision',r.decision)}${record('Rubric assessment',r.comments)}${record('Accuracy / public value',r.accuracy+' / '+r.public_value)}${record('Review cost',money(r.fee_kobo)+' · '+r.minutes+' minutes')}</dl>`).join('')}</details>`:''}</article>`;}
async function myRecords(section){const {projects}=await api('/projects');let cards=[];for(const p of projects){detail=await api('/projects/'+p.id);if(section==='credentials'){cards.push(...detail.credentials.filter(c=>c.contributor_id===currentUser.id||currentUser.roles.includes('coordinator')).map(c=>`<div class="item">${badge(c.correction_status,c.correction_status==='revoked'?'red':'')}<h3>${esc(detail.tasks.find(t=>t.id===c.task_id)?.title)}</h3><p>${esc(p.title)} · ${fmt(c.issued_at)}</p><p class="credential-id">${esc(c.id)}</p><p class="muted">Visibility: ${esc(c.visibility)}</p><div class="actions">${c.contributor_id===currentUser.id?button('credential-visibility',c.visibility==='private'?'Make this record public':'Make this record private',`data-id="${c.id}" data-visibility="${c.visibility==='private'?'public':'private'}"`):''}${c.visibility==='public'?link('/credentials/'+c.id,'Public verification page','button-secondary small'):''}${currentUser.roles.includes('coordinator')?button('credential-correction','Correct or withdraw record',`data-id="${c.id}"`):''}</div></div>`));}else{const list=section==='review'?detail.contributions.filter(c=>detail.reviewAssignments.some(a=>a.contribution_id===c.id&&a.reviewer_id===currentUser.id)):detail.contributions.filter(c=>c.contributor_id===currentUser.id);cards.push(...list.map(c=>`<div class="item">${badge(c.status)}<h3>${esc(detail.tasks.find(t=>t.id===c.task_id)?.title)}</h3><p>${esc(p.title)}</p>${link('/app/projects/'+p.id,'Open project & evidence →','button-secondary small')}</div>`));}}const titles={review:'Your independent review queue',contributions:'Your contribution records',credentials:'Verified credentials'};workspace(`<div class="section-head"><div><div class="eyebrow">Supervised service</div><h1>${titles[section]}</h1><p class="muted">${section==='credentials'?'The same verified credit for paid and volunteer work.':'Projects and review assignments are selected by the coordinator.'}</p></div></div><div class="stack">${cards.join('')||empty('No records here yet.','Your assigned work and its review records will appear as projects progress.')}</div>`,section);}
async function gates(){const {gates}=await api('/gates');workspace(`<div class="section-head"><div><div class="eyebrow">Evidence before expansion</div><h1>Pilot evidence & gates</h1><p class="muted">Dates are proposals. Each gate records proceed, retest, or redesign.</p></div>${currentUser.roles.includes('coordinator')?button('gate','Record a gate decision','','button'):''}</div><div class="cards">${[[1,'Pilot A review','9 Nov 2026'],[2,'Both pilots','7 Dec 2026'],[3,'Service readiness','8 Mar 2027']].map(([n,title,when])=>{const g=gates.find(g=>g.gate===n);return `<div class="card"><div class="tile-label">Gate ${n} / ${when}</div><h3>${title}</h3>${badge(g?.decision||'Not assessed','gray')}<p>${esc(g?.evidence||'Measured pilot evidence and a decision have not yet been recorded.')}</p>${g?`<small>Recorded ${fmt(g.recorded_at)}</small>`:''}</div>`;}).join('')}</div>${notice('Recording a decision does not automatically open public intake, pooled funding, or wider participation. Each capability has its own readiness conditions.','blue')}<div class="spacer">${link('/roadmap','Full pilot measures & readiness plan →')}</div>`,'gates');}

function participate(){
 const mode=new URLSearchParams(location.search).get('role')||'individual';
 const journeys={
  individual:{heading:'Your skills can move a need forward.',intro:'You can contribute paid work, volunteer time, professional expertise, or resources. Find work that fits your skills.',steps:[['1','Choose the way you can help','Choose a project and review its available tasks.'],['2','Understand your assignment','Read the project need, task brief, reward or volunteer terms, deadline, rubric, and evidence standard.'],['3','Contribute and submit proof','Accept the terms before starting. Submit your work and evidence files for independent review.'],['4','Receive a verified record','After approval and the acceptance window, get a contribution credential. Paid assignments also have a recorded external payment.']]},
  organisation:{heading:'A clear route from support to evidence.',intro:'NGOs, businesses, institutions, community groups, and other organisations can bring a public need, fund tasks, offer materials, or provide capable contributors.',steps:[['1','Start with a public-good need','Work with CivicBench to complete the need record, choose a named steward, and screen feasibility and eligibility.'],['2','Agree the support and responsibilities','Name the people authorised to steward, sign off, and accept work. Record money or materials, the written agreement, and payment or delivery route.'],['3','Follow the work against the rubric','The project can mix funded and volunteer tasks. Independent reviewers assess evidence; your acceptance window is 72 hours on rubric grounds.'],['4','See the outcome and follow through','Track verified completion separately from impact. Review outstanding needs, sharing with beneficiaries, follow-up dates, costs, and whether to fund more.']]},
  reviewer:{heading:'Bring your expertise. Keep review independent.',intro:'Reviewers and stewards have different responsibilities. You can hold several roles, but never review work you contributed to or funded.',steps:[['1','Join the vetted panel or steward a need','A coordinator assigns roles based on expertise, conflict checks, and capacity. Review assignments rotate.'],['2','Use the rubric agreed before work starts','Reviewers assess source accuracy first, then public value. Stewards structure tasks and manage milestones.'],['3','Record evidence and clear feedback','Approve work or return it for rework. Reviewer fees are flat and independent of outcome; donated time still counts as a cost.'],['4','Close the loop','The steward manages the acceptance window, credentials, public outcome record, dissemination, and follow-up. Disagreements use a three-person panel.']]}
 };const j=journeys[mode]||journeys.individual;
 page('<div class="wrap section"><div class="eyebrow">Individuals & organisations</div><div class="pill-tabs"><a class="button-secondary" href="/participate?role=individual">For individuals</a><a class="button-secondary" href="/participate?role=organisation">For organisations</a><a class="button-secondary" href="/participate?role=reviewer">Reviewers & stewards</a></div><h1 style="font-size:3rem;max-width:900px">'+j.heading+'</h1><p class="muted prose">'+j.intro+'</p><div class="journey-page-grid"><div>'+j.steps.map(([n,title,copy])=>'<article class="timeline"><time>0'+n+' /</time><div><h3>'+title+'</h3><p>'+copy+'</p></div></article>').join('')+'</div><aside class="journey-aside"><img src="/images/'+(mode==='organisation'||mode==='reviewer'?'library-collaboration':'community-volunteers')+'.webp" alt="Nigerian participants working together"/><div><h3>One person. Several ways to help.</h3><p>Roles can overlap. Work and funding responsibilities stay clear, and conflicts are checked before review.</p>'+notice('Individuals and organisations can propose needs for review.','blue')+link('/app/login','Open your workspace →','button')+'</div></aside></div></div>');
}
function credits(){page('<div class="wrap section prose"><div class="eyebrow">Authentic Nigerian photography</div><h1 style="font-size:3rem">People and place, honestly represented.</h1><p>These photographs provide Nigerian context. They do not show CivicBench projects or imply endorsement, sponsorship, or partnership.</p><div class="card"><h3>Community volunteering in Lagos</h3><p>Lagos Food Bank Initiative · photograph taken 15 May 2021. Used under the <a href="https://www.pexels.com/license/">Pexels licence</a>. Resized and cropped for display.</p><a href="https://www.pexels.com/photo/happy-volunteers-carrying-boxes-8061641/">Original photograph →</a></div><div class="card spacer"><h3>Collaborative knowledge work in Nigeria</h3><p>“Wiki Loves Library NIgeria 41”, James Rhoda, 15 December 2022. <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. Resized and cropped for display; the adapted photo retains that licence.</p><a href="https://commons.wikimedia.org/wiki/File:Wiki_Loves_Library_NIgeria_41.jpg">Original photograph & author credit →</a></div><p class="hero-note">All platform mockups use illustrative sample content. They are not reported pilot achievements.</p></div>');}

async function route(){const path=location.pathname;if(await communityRoute(path))return;document.title='CivicBench — Public needs. Verified action.';try{if(path==='/')return await home();if(path==='/projects')return await projects();if(path.startsWith('/projects/'))return await publicProject(path.split('/')[2]);if(path==='/participate')return participate();if(path==='/credits')return credits();if(path==='/approach')return approach();if(path==='/roadmap')return roadmap();if(path.startsWith('/credentials'))return await credential(path.split('/')[2]);if(path==='/app/register')return await register();if(path==='/app/login')return await login();if(path.startsWith('/app')){if(!await ensureUser())return;const section=path.split('/')[2];if(section==='projects'&&path.split('/')[3])return await privateProject(path.split('/')[3]);if(['contributions','review','credentials'].includes(section))return await myRecords(section);if(section==='gates')return await gates();await dashboard(section);if(section==='projects'&&new URLSearchParams(location.search).has('structure')&&currentUser.roles.includes('coordinator'))document.querySelector('[data-action="new-need"]')?.click();return;}page(`<div class="wrap section">${empty('This page has moved.','CivicBench now starts with needs and projects.')}${link('/','Back to CivicBench')}</div>`);}catch(e){page(`<div class="wrap section">${notice(esc(e.message),'error')}${link('/app','Back to workspace')}</div>`);}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;if(await communityAction(event,el))return;const action=el.dataset.action,id=el.dataset.id,p=detail?.project;try{
 if(action==='close-modal'){modal.close();return;}
 if(action==='logout'){await fetch('/api/logout',{method:'POST'});sessionStorage.removeItem('cb_session');currentUser=null;location.href='/';return;}
 if(action==='local-login'&&preview){sessionStorage.setItem('cb_session','preview.'+el.dataset.role);location.href='/app';return;}
 if(action==='tab'){activeTab=el.dataset.tab;await privateProject(p.id);return;}
 if(action==='new-need'){const sourceProposal=JSON.parse(sessionStorage.getItem('cb_proposal')||'null');openForm('Start with a need','Complete the canonical 12-item record. Incomplete needs can return for clarification; publishing and funding wait for screening.',input('title','Project title')+NEED_FIELDS.map(([key,label,help])=>key==='targetDate'?input(key,label,'date',true,help):area(key,label,help)).join('')+input('stewardId','Steward account ID','text',true,'An existing account chosen for this project.')+area('closingRule','Closing rule','Re-plan with a new date or close unresolved if progress stalls.')+input('previousId','Rejected need ID (optional)','text',false,'A revised proposal becomes a new linked record.',el.dataset.previous||''),'Create need',async data=>{const {id}=await api('/projects',{...data,proposalId:sourceProposal?.id||null});sessionStorage.removeItem('cb_proposal');location.href='/app/projects/'+id;});if(sourceProposal){const f=document.getElementById('modal-form');for(const key of ['title','problem','audience','outcome','permissions','safety','resources'])if(f.elements[key])f.elements[key].value=sourceProposal[key]||'';f.elements.proposer.value='Account '+sourceProposal.proposer_id;}return;}
 if(action==='screen'){openForm('Screen & structure','Record completeness, feasibility, eligibility, and the decision reason. Rejection is terminal for this need.',select('decision','Decision',[['structured','Pass: structure into a project'],['clarification','Return for clarification'],['rejected','Reject with a reason']])+area('reason','Decision reason')+ELIGIBILITY.map((key,i)=>check(key,['Public benefit','Lawful authority & permissions','Privacy & consent','Contributor safety','Clear deliverables & evidence','Independent verification'][i])).join(''),'Record screening',data=>api(`/projects/${p.id}/screen`,{decision:data.decision,reason:data.reason,checks:Object.fromEntries(ELIGIBILITY.map(key=>[key,data[key]]))}));const form=document.getElementById('modal-form');const change=()=>form.querySelectorAll('input[type=checkbox]').forEach(c=>c.required=form.elements.decision.value==='structured');form.elements.decision.addEventListener('change',change);change();return;}
 if(action==='outcome'){const transitions={structured:['structured','active','closed'],active:['active','completed','closed'],completed:['completed','closed']};openForm('Completion & public impact','Record achievements and outstanding needs separately. Completion requires accepted work; closure needs a reason.',select('executionStatus','Execution status',transitions[p.execution_status]||[p.execution_status],p.execution_status)+select('impactStatus','Impact status',IMPACT,p.impact_status)+area('completionRecord','Completion or closure record','Verified delivery and hand-over, or the reason for closure.',p.completion_record,false)+area('impactEvidence','Impact evidence','What evidence supports this impact status?',p.impact_evidence)+area('outstandingNeed','Outstanding need','What remains and who can act?',p.outstanding_need)+input('nextReview','Next impact review date','date',true,'',p.next_impact_review_date||'')+area('disseminationRecord','Who received the result & how','Record agreed sharing channels and recipients.',p.dissemination_record,false),'Save outcome',data=>api(`/projects/${p.id}/outcome`,data));return;}
 if(action==='publish'){openForm('Publish a moderated project record','Publish only the approved public summary and outcome record. Private submissions and evidence files remain restricted.',area('publicSummary','Public summary','For completed work, independently approved results must be accepted first.',p.public_summary)+check('privacyChecked','I checked every public field for privacy, neutral framing, and unsupported claims.'),'Publish public record',data=>api(`/projects/${p.id}/publish`,data));return;}
 if(action==='correction'){openForm('Correct the public record','The correction will be visible on the project page.',area('summary','Correction, reason & follow-through'),'Record correction',data=>api(`/projects/${p.id}/correction`,data));return;}
 if(action==='funding'){openForm('Record money or material funding','Record an external agreement. No money is collected or moved by this form.',select('type','Resource type',['money','material'])+input('funderId','Funder account ID')+input('funderName','Funder name')+input('amount','Money amount (₦)','text',false,'Leave blank for materials.')+input('materialDescription','Material description','text',false)+input('quantity','Material quantity','number',false)+input('unit','Material unit','text',false)+select('status','Commitment status',['pledged','committed','held','released','refunded'])+area('agreementRef','Written agreement reference')+area('paymentRoute','Payment or material delivery route')+area('deliveryRecord','Delivery record (if received)','Actual delivery or transfer evidence.', '',false),'Save commitment',data=>api(`/projects/${p.id}/funding`,{...data,amountKobo:data.type==='money'?kobo(data.amount):0,quantity:Number(data.quantity||0)}));return;}
 if(action==='new-task'){openForm('Structure a bounded task','State the paid or volunteer terms, rubric, evidence, and sign-offs before assignment. Reward is per contributor slot.',input('title','Task title')+select('mode','Terms',['volunteer','paid'])+area('brief','Task brief & deliverable')+area('rubric','Versioned review rubric','Include accuracy and public-value criteria; no unilateral changes.')+area('evidenceStandard','Evidence standard')+area('terms','Assignment terms','Volunteer work has no implied payment. Paid work states the agreed reward.')+input('reward','Reward per contributor (₦)','text',false)+input('deadline','Deadline','date')+input('capacity','Contributor slots','number',true,'Work can be split across contributors.','1')+select('reviewsRequired','Independent reviews required',['1','2'])+area('stewardSignoff','Steward sign-off reference')+area('funderSignoff','Funder sign-off reference (paid only)','Required before a paid task opens.','',false)+input('acceptanceBy','Funder acceptance account ID (paid only)','text',false),'Create draft task',data=>api(`/projects/${p.id}/tasks`,{...data,rewardKobo:data.mode==='paid'?kobo(data.reward):0,capacity:Number(data.capacity),reviewsRequired:Number(data.reviewsRequired)}));return;}
 if(action==='allocate'){openForm('Allocate committed funding','Funding must belong to this project and be committed or held. Allocation cannot exceed the unallocated amount.',select('fundingId','Funding commitment',detail.funding.filter(f=>f.type==='money'&&['committed','held'].includes(f.status)).map(f=>[f.id,`${f.funder_name} · ${money(f.amount_kobo)}`]))+input('amount','Allocation amount (₦)'),'Allocate funding',data=>api(`/tasks/${id}/allocate`,{fundingId:data.fundingId,amountKobo:kobo(data.amount)}));return;}
 if(action==='open-task'){el.disabled=true;await api(`/tasks/${id}/open`,{});toast('Task opened for supervised assignment.');await route();return;}
 if(action==='assign'){openForm('Supervised contributor assignment','Assign a vetted contributor to one of the task’s slots. The contributor must accept terms before starting.',input('contributorId','Contributor account ID'),'Assign contributor',data=>api(`/tasks/${id}/assign`,data));return;}
 if(action==='agree'){const t=detail.tasks.find(t=>t.id===id);openForm('Agree before you start',`${esc(t.mode==='paid'?money(t.reward_kobo)+' per contribution':'Volunteer assignment · no payment is implied')}`,`<div class="field full"><pre>${esc(t.terms)}</pre></div>`+check('agree','I understand and agree to these terms, the rubric, deadline, and evidence standard.'),'Accept assignment terms',data=>api(`/tasks/${id}/agree`,data));return;}
 if(action==='submit'){openForm('Submit your contribution','Describe the deliverable and method. After saving, upload the proof files required by the evidence standard.',area('submission','Completed work, method & references'),'Save contribution',data=>api(`/tasks/${id}/submit`,data));return;}
 if(action==='upload-evidence'){openForm('Upload private evidence','PDF, PNG, JPEG, or text. Up to 512 KB per file. Evidence is stored privately and shared only with authorised participants.',`<div class="field full"><label for="evidence-file">Evidence file</label><input id="evidence-file" name="file" type="file" required accept="application/pdf,image/png,image/jpeg,text/plain"/></div>`,'Upload evidence',async(data,form)=>{const file=form.elements.file.files[0];if(file.size>512*1024)throw new Error('Choose a file of at most 512 KB.');await api(`/contributions/${id}/evidence`,null,{method:'POST',headers:{'Content-Type':file.type||'text/plain','X-Filename':encodeURIComponent(file.name),'X-File-Size':String(file.size)},body:file});});return;}
 if(action==='download-evidence'){const response=await fetch('/api/v2/evidence/'+id,{headers:{Authorization:'Bearer '+sessionStorage.getItem('cb_session')}});if(!response.ok)throw new Error((await response.json()).error);const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=el.textContent;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);return;}
 if(action==='assign-reviewer'){openForm('Assign an independent reviewer','Reviewers must be vetted, rotated, and free of contributor or funder conflicts. Stored proof is required first.',input('reviewerId','Reviewer account ID'),'Assign reviewer',data=>api(`/contributions/${id}/assign-reviewer`,data));return;}
 if(action==='review'){const c=detail.contributions.find(c=>c.id===id),t=detail.tasks.find(t=>t.id===c.task_id);openForm('Review against the agreed rubric','Accuracy comes first. Review fees are flat and independent of the outcome.',`<div class="field full"><strong>Rubric v${t.rubric_version}</strong><pre>${esc(t.rubric)}</pre></div>`+select('decision','Review decision',[['approved','Approve'],['rejected','Return for rework']])+input('accuracy','Accuracy score / 100','number')+input('publicValue','Public value score / 100','number')+area('comments','Rubric assessment, method & feedback')+input('fee','Agreed flat review fee (₦)','text',true,'Enter 0 if donated.','0')+input('minutes','Review time (minutes)','number')+check('noConflict','I have declared my conflicts and neither contributed to nor funded this project.')+`<label class="checkbox-field"><input type="checkbox" name="accuracyPassed"/><span>The work passed the independent accuracy gate.</span></label>`,'Save independent review',data=>api(`/contributions/${id}/review`,{...data,accuracy:Number(data.accuracy),publicValue:Number(data.publicValue),feeKobo:kobo(data.fee),minutes:Number(data.minutes)}));return;}
 if(action==='finalize'){el.disabled=true;await api(`/contributions/${id}/finalize`,{});toast('Acceptance finalised and verified credential issued.');await route();return;}
 if(action==='dispute'){openForm('Contest on rubric grounds','A disagreement does not bypass independent verification. A coordinator records the panel decision.',area('reason','Rubric-based reason and supporting evidence'),'Record dispute',data=>api(`/contributions/${id}/dispute`,data));return;}
 if(action==='resolve-dispute'){openForm('Record independent panel decision','The panel has three distinct vetted reviewers with no contributor or funder conflicts.',input('panelIds','Three reviewer account IDs, comma separated')+select('decision','Panel outcome',['approved','rejected'])+area('reason','Panel reasoning against the agreed rubric')+check('accuracyPassed','The panel assessed technical accuracy independently.'),'Record panel decision',data=>api(`/contributions/${id}/resolve`,{...data,panelIds:data.panelIds.split(',').map(s=>s.trim())}));return;}
 if(action==='payment'){openForm('Record an actual external payment','This records evidence of a payment already made. It does not transfer funds or create escrow.',input('route','Licensed provider or written manual agreement')+input('reference','External payment reference')+input('paidAt','Payment date','date')+check('alreadyPaid','The agreed reward was actually paid through the stated external route.'),'Record payment',data=>api(`/contributions/${id}/payment`,data));return;}
 if(action==='cost'){openForm('Record the true cost','Record donated time at the agreed shadow rate as well as direct costs.',select('category','Category',['Screening & structuring','Steward & coordination','Independent review','Credential verification','Tools & data','Other'])+input('minutes','Time in minutes','number',true,'','0')+input('rate','Hourly rate or shadow rate (₦)','text',true,'','0')+input('direct','Direct expense (₦)','text',true,'','0')+select('donated','Time basis',[['yes','Donated time'],['no','Paid time']])+area('note','Basis & cost note'),'Record cost',data=>api(`/projects/${p.id}/costs`,{category:data.category,minutes:Number(data.minutes),rateKobo:kobo(data.rate),directKobo:kobo(data.direct),donated:data.donated==='yes',note:data.note}));return;}
 if(action==='grant-role'){openForm('Assign a vetted role','Existing accounts can hold several roles. Independent review conflict checks still apply.',input('userId','Existing account ID')+select('role','Role',['steward','contributor','reviewer','funder']),'Assign role',data=>api('/roles',data));return;}
 if(action==='gate'){openForm('Record an evidence gate','Use measured delivery, quality, review, cost, and repeat funding evidence. An untested assumption is not a passed gate.',select('gate','Gate',[['1','Gate 1 · Pilot A'],['2','Gate 2 · Both pilots'],['3','Gate 3 · Service readiness']])+select('decision','Decision',['proceed','retest','redesign'])+area('evidence','Measured evidence & decision rationale'),'Save gate decision',data=>api('/gates',{...data,gate:Number(data.gate)}));return;}
 if(action==='credential-visibility'){openForm('Choose credential visibility','Public records disclose the project, task, verification decision, issue date, and correction status. Private evidence and account identity remain hidden.',check('consent',el.dataset.visibility==='public'?'I want this contribution record to be publicly verifiable.':'I want this contribution record to be private.'),'Save visibility',()=>api('/credentials/'+id,{visibility:el.dataset.visibility}));return;}
 if(action==='credential-correction'){openForm('Correct or withdraw a credential','The existing verification ID remains, with its correction status and reason.',select('correctionStatus','Action',[['corrected','Record a correction'],['revoked','Withdraw the credential']])+area('reason','Correction or withdrawal reason'),'Save correction',data=>api('/credentials/'+id,data));return;}
 }catch(e){toast(e.message);el.disabled=false;}});
modal.addEventListener('click',e=>{if(e.target===modal){const rect=modal.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)modal.close();}});
setupCommunity({api,esc,fmt,money,button,link,page,workspace,input,area,select,check,openForm,record,empty,notice,toast,ensureUser,login,user:()=>currentUser});
await route();

web/community.mjs.content:
let c,data,recapData,recapStep=0;const E=v=>c.esc(v),B=(a,l,attrs='')=>c.button(a,l,attrs,'button-secondary small'),L=(p,l)=>c.link(p,l,'button');
export function setup(context){c=context}
const selected=()=>[...document.querySelectorAll('[name="entryId"]:checked')].map(el=>el.value);
function entries(rows,choose=true){return rows.length?rows.map(r=>`<article class="item"><div class="label-line"><span class="badge ${r.correction_status==='revoked'?'red':''}">${E(r.correction_status==='revoked'?'Withdrawn':r.mode==='volunteer'?'Verified volunteer work':'Verified paid work')}</span><small>${c.fmt(r.issued_at)}</small></div><h3>${E(r.task_title)}</h3><p>${E(r.project_title)}</p>${r.correction_reason?`<p>${E(r.correction_reason)}</p>`:''}<div class="actions">${choose&&r.correction_status!=='revoked'?`<label class="checkbox-field"><input type="checkbox" name="entryId" value="${E(r.id)}" checked> Include in my CV</label>`:''}${r.correction_status!=='revoked'?B('share-entry','Share contribution',`data-id="${E(r.id)}"`):''}<a href="/credentials/${E(r.id)}${location.pathname.startsWith('/s/')?'?share='+location.pathname.split('/')[2]:''}">Verification record →</a>${choose?B('affiliate','Add to organisation recap',`data-id="${E(r.id)}"`):''}</div></article>`).join(''):c.empty('Your record starts with your first contribution.','Reviewed and accepted work will appear here.');}
export async function route(path){if(path.startsWith('/s/')){const id=path.split('/')[2];try{data=(await c.api('/public/shares/'+id)).share}catch(err){try{data=(await c.api('/shares/'+id)).share}catch{c.page(`<div class="wrap section prose"><h1>Record unavailable.</h1><p>This link may be private or no longer shared.</p>${L('/','Back to CivicBench')}</div>`);return true}}sharePage(data,id);return true}
 const sections=['proposals','propose','organisation','cv','recap','admin','activity'];const section=path.split('/')[2];if(!path.startsWith('/app')||!sections.includes(section))return false;if(!await c.ensureUser())return true;
 if(section==='propose')await proposalForm();if(section==='proposals'||section==='admin')await proposals(section==='admin');if(section==='organisation')await organisations();if(section==='cv')await cv();if(section==='recap')await recapView();if(section==='activity')await activity();return true;}
async function proposalForm(){const orgs=(await c.api('/organisations')).organisations;const previous=new URLSearchParams(location.search).get('previous')||'';c.workspace(`<div class="section-head"><div><div class="eyebrow">Private submission</div><h1>Propose a need.</h1><p>Tell us what needs to change. We’ll review it with you.</p></div></div><form id="need-proposal" class="card prose"><div class="proposal-step"><h3>1. The need</h3>${c.input('title','A clear title')}${c.area('problem','What is happening?','Include what you have observed or can support with evidence.')}${c.input('audience','Where is it, and who would benefit?')}</div><div class="proposal-step" hidden><h3>2. Public benefit</h3>${c.area('outcome','What would improvement look like?')}${c.area('permissions','Who can authorise work here?','It’s okay to say you don’t know yet.')}${c.area('safety','Any safety, privacy or consent concerns?','Enter None known if you are unsure of any concerns.')}</div><div class="proposal-step" hidden><h3>3. Follow-up</h3>${c.select('participation','How can you be involved?',['Proposer only','I can help steward','I can contribute','My organisation can support'])}${c.select('organisationId','Proposing as',[['','Myself'],...orgs.map(o=>[o.id,o.name])])}${c.area('resources','Known support or resources (optional)','','',false)}${c.input('timing','Desired timing (optional)','text',false)}<label class="checkbox-field"><input name="consent" type="checkbox" required> I understand that review does not guarantee funding or delivery.</label></div><div class="form-error" role="alert"></div><div class="actions"><button type="button" class="button-secondary" id="proposal-back" hidden>Back</button><button class="button" id="proposal-next">Continue →</button></div></form>`,'proposals');let step=0;const form=document.getElementById('need-proposal'),parts=[...form.querySelectorAll('.proposal-step')];const show=()=>{parts.forEach((p,i)=>{p.hidden=i!==step;p.querySelectorAll('input,textarea,select').forEach(el=>el.disabled=i!==step)});form.querySelector('#proposal-back').hidden=step===0;form.querySelector('#proposal-next').textContent=step===2?'Submit for review →':'Continue →'};form.querySelector('#proposal-back').onclick=()=>{step--;show()};form.onsubmit=async e=>{e.preventDefault();if(step<2){step++;show();return}parts.forEach(p=>p.querySelectorAll('input,textarea,select').forEach(el=>el.disabled=false));const values=Object.fromEntries(new FormData(form));try{form.querySelector('#proposal-next').disabled=true;await c.api('/proposals',{...values,previousId:previous});location.href='/app/proposals'}catch(err){form.querySelector('.form-error').textContent=err.message;show();form.querySelector('#proposal-next').disabled=false}};show()}
async function proposals(admin){const user=c.user();if(admin&&!user.roles.includes('coordinator'))throw new Error('Administrator access required.');const rows=(await c.api('/proposals')).proposals;const interests=admin?(await c.api('/interests')).interests:[];data=rows;c.workspace(`<div class="section-head"><div><div class="eyebrow">${admin?'Administration':'Your proposals'}</div><h1>${admin?'Review queue.':'Needs you’ve proposed.'}</h1></div>${L('/app/propose','＋ Propose a need')}</div>${rows.length?`<div class="stack">${rows.map(p=>`<article class="item"><div class="label-line"><span class="badge ${p.status==='clarification'?'amber':''}">${E(p.status)}</span><small>${c.fmt(p.updated_at)}</small></div><h3>${E(p.title)}</h3><p>${E(p.problem)}</p><details><summary>Proposal details</summary><dl>${['audience','outcome','permissions','safety','resources','timing','participation'].map(k=>c.record(k.replace(/^./,v=>v.toUpperCase()),p[k])).join('')}${p.reply?c.record('Clarification',p.reply):''}</dl></details>${p.feedback?`<p class="notice">${E(p.feedback)}</p>`:''}<div class="actions">${admin&&!['approved','rejected'].includes(p.status)?B('proposal-review','Review proposal',`data-id="${p.id}"`):''}${admin&&p.status==='approved'?B('structure-proposal','Structure project',`data-id="${p.id}"`):''}${!admin&&p.status==='clarification'?B('proposal-reply','Add clarification',`data-id="${p.id}"`):''}${!admin&&p.status==='rejected'?c.link('/app/propose?previous='+p.id,'Revise as a new proposal'):''}</div></article>`).join('')}</div>`:c.empty(admin?'Nothing awaiting review.':'Have a need in mind?','Proposals are private until reviewed and structured.')}${admin&&interests.length?'<section class="section"><h3>Requests to contribute</h3>'+interests.map(i=>'<div class="item"><strong>'+E(i.name)+'</strong> · '+E(i.title)+'<p>'+E(i.note)+'</p><small>Account '+E(i.user_id)+'</small><p>'+c.link('/app/projects/'+i.project_id,'Open project')+'</p></div>').join('')+'</section>':''}`,'proposals')}
async function organisations(){const rows=(await c.api('/organisations')).organisations;data=rows;const oid=new URLSearchParams(location.search).get('id');if(oid){const d=await c.api('/organisations/'+oid);data=d;c.workspace(`<div class="section-head"><div><div class="eyebrow">Organisation workspace</div><h1>${E(d.organisation.name)}</h1><p>${E(d.organisation.description)}</p></div>${c.link('/app/recap?organisation='+oid,'Create Impact Recap','button')}</div><div class="two-col"><div class="card"><h3>Your people</h3>${d.members.map(m=>`<p><strong>${E(m.name)}</strong> <span class="badge">${E(m.role)}</span></p>`).join('')}${B('member','Add an existing member',`data-id="${oid}"`)}</div><div class="card"><h3>Recorded support</h3>${d.support.length?d.support.map(f=>`<p><a href="/app/projects/${f.project_id}">${E(f.title)}</a><br>${f.type==='money'?c.money(f.amount_kobo):`${f.quantity} ${E(f.unit)} · ${E(f.material_description)}`} <span class="badge">${E(f.status)}</span></p>`).join(''):'<p>No confirmed support records yet.</p>'}${c.user().roles.includes('coordinator')?B('org-support','Link confirmed support',`data-id="${oid}"`):''}</div></div>`,'organisation');return}c.workspace(`<div class="section-head"><h1>Your organisations.</h1>${B('new-org','＋ Create organisation')}</div>${rows.length?`<div class="cards">${rows.map(o=>`<a href="/app/organisation?id=${o.id}" class="card"><span class="badge">${E(o.membership_role)}</span><h3>${E(o.name)}</h3><p>${E(o.description)}</p><span>Open workspace →</span></a>`).join('')}</div>`:c.empty('Bring your organisation.','Create a workspace for your team and project support.')}`,'organisation')}
async function cv(){data=await c.api('/civic-cv');c.workspace(`<div class="section-head"><div><div class="eyebrow">Your verified contribution record</div><h1>My Civic CV.</h1><p>Choose the contributions you want to include.</p></div><div class="actions">${B('share-cv','Share Civic CV')}${B('print-record','Print / save PDF')}</div></div><section class="cv-sheet"><h2>${E(data.name)}</h2><div class="stack">${entries(data.entries)}</div></section><section class="section"><h3>Your shared records</h3>${data.shares.length?data.shares.map(s=>`<div class="item"><a href="/s/${s.id}">${E(s.type==='cv'?'Civic CV':s.type==='recap'?'Impact Recap':'Contribution')}</a> <span class="badge">${E(s.visibility)}</span> ${B('share-visibility','Change visibility',`data-id="${s.id}"`)} ${B('copy-link','Copy link',`data-url="${location.origin}/s/${s.id}"`)}</div>`).join(''):'<p class="muted">No shared records yet.</p>'}</section>`,'cv')}
async function recapView(){const orgs=(await c.api('/organisations')).organisations;const org=new URLSearchParams(location.search).get('organisation')||'';c.workspace(`<div class="section-head"><div><div class="eyebrow">Your contribution story</div><h1>Impact Recap.</h1></div></div><form id="recap-filter" class="filter-bar">${c.select('organisationId','Recap for',[['','Myself'],...orgs.map(o=>[o.id,o.name])],org)}${c.input('from','From','date',true,'',new Date().getFullYear()+'-01-01')}${c.input('to','To','date',true,'',new Date().toISOString().slice(0,10))}<button class="button">Generate recap →</button></form><div id="recap-result"></div>`,'recap');document.getElementById('recap-filter').onsubmit=async e=>{e.preventDefault();try{recapData=(await c.api('/recap',Object.fromEntries(new FormData(e.currentTarget)))).recap;recapData.organisationId=e.currentTarget.elements.organisationId.value;recapStep=0;renderRecap()}catch(err){c.toast(err.message)}};document.getElementById('recap-filter').requestSubmit()}
function slides(d){const active=d.entries.filter(e=>e.correction_status!=='revoked');const projects=d.projects||[];return [[d.name,'Your Impact Recap',c.fmt(d.from)+' – '+c.fmt(d.to)],[String(active.length),'verified contributions',`${active.filter(e=>e.mode==='volunteer').length} volunteer · ${active.filter(e=>e.mode==='paid').length} paid`],[String(projects.length),'projects supported or contributed to','Each project is counted once.'],[d.organisationId?c.money(d.moneyKobo):'Work you can point to.',d.organisationId?'confirmed financial support':'Reviewed. Accepted. Recorded.',d.organisationId?`${d.materials.length} types of delivered materials. Money and materials are counted separately.`:active.map(e=>e.task_title).slice(0,3).join(' · ')||'Your first verified contribution will start the story.'],[`${projects.filter(p=>p.execution_status==='completed').length} completed`,'The wider needs',`${projects.filter(p=>p.impact_status==='resolved').length} resolved · ${projects.filter(p=>p.impact_status==='partly resolved').length} partly resolved · ${projects.filter(p=>!['resolved','partly resolved'].includes(p.impact_status)).length} awaiting resolution or assessment`]]}
function renderRecap(){const s=slides(recapData)[recapStep];document.getElementById('recap-result').innerHTML=`<div class="two-col"><article class="recap-card"><div class="recap-brand">CivicBench ↗ <small>${E(recapData.name)}</small></div><div><h2>${E(s[0])}</h2><h3>${E(s[1])}</h3><p>${E(s[2])}</p></div><div><div class="recap-progress">${slides(recapData).map((_,i)=>`<i class="${i<=recapStep?'on':''}"></i>`).join('')}</div><div class="actions">${B('recap-prev','← Back')}${B('recap-next','Next →')}<span>${recapStep+1} / 5</span></div></div></article><aside class="card"><h3>Your story. Your choice.</h3><p>${recapData.organisationId?'Team contributions appear only with the contributor’s consent and public verification.':'Only your reviewed and accepted contributions are counted.'}</p><div class="actions">${B('share-recap','Share full recap')}${B('download-card','Download this card')}${B('print-record','Print / save PDF')}</div><p class="hero-note">Generated ${c.fmt(recapData.generatedAt)}. Contribution completion and project impact are shown separately.</p>${recapData.entries.length?'':c.notice('No verified contributions in this period.','blue')}</aside></div>`}
function sharePage(d,id){data=d;const active=d.entries.filter(r=>r.correction_status!=='revoked');c.page(`<div class="wrap section prose shared-record"><div class="eyebrow">${E(d.type==='cv'?'Civic CV':d.type==='contribution'?'Verified contribution':'Impact Recap')}</div><h1 style="font-size:3rem">${E(d.name)}</h1><p>${d.from?c.fmt(d.from)+' – '+c.fmt(d.to)+' · ':''}Generated ${c.fmt(d.generatedAt)}</p><div class="actions">${B('native-share','Share',`data-url="${location.origin}/s/${id}"`)}${B('copy-link','Copy link',`data-url="${location.origin}/s/${id}"`)}${B('download-card','Download card')}${B('print-record','Print / save PDF')}</div><div class="chips"><span class="badge">${active.length} verified contributions</span></div>${entries(d.entries,false)}${d.type==='recap'&&d.projects?`<div class="card spacer"><h3>Project outcomes</h3>${d.projects.map(p=>`<p>${E(p.title)} <span class="badge">${E(p.execution_status)}</span> <span class="badge amber">${E(p.impact_status)}</span></p>`).join('')}<p class="hero-note">Project statuses are a snapshot from the generation date.</p></div>`:''}<p class="hero-note">Verification checked ${c.fmt(d.verificationCheckedAt)}. Withdrawn records are excluded from verified totals.</p></div>`)}
async function activity(){data=(await c.api('/activity')).activity;c.workspace(`<h1>Activity history.</h1><div class="stack">${data.map(a=>`<div class="item"><span class="badge">${E(a.action)}</span> <small>${c.fmt(a.created_at)}</small><p>${E(a.reason)}</p><small>Account ${E(a.actor_id)} · ${E(a.record_id)}</small></div>`).join('')||c.empty('No recorded changes yet.','Screening decisions will appear here.')}</div>`,'admin')}
function shareForm(type,ids,source={}){c.openForm('Share '+(type==='cv'?'your Civic CV':type==='recap'?'your Impact Recap':'this contribution'),'Choose who can see this record.',c.select('visibility','Visibility',[['private','Private — only me'],['link','Anyone with the link'],['public','Public']])+c.check('consent','I agree to share these selected records and my display name. Private evidence and payment details stay private.'),'Create share',async v=>{const r=await c.api('/shares',{...source,...v,type,entryIds:ids});location.href='/s/'+r.id})}
export async function action(event,el){const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='project-interest'){try{await c.api('/me')}catch{sessionStorage.setItem('cb_after_login',location.pathname);location.href='/app/login';return true}c.openForm('How can you help?','The project team will review your request before assigning a task.',c.area('note','Your skills, availability and preferred paid or volunteer work'),'Send request',async v=>{await c.api('/projects/'+id+'/interest',v);c.toast('Request sent to the project team.')});return true}
 if(a==='proposal-review'){c.openForm('Review proposal','Keep your decision clear for the proposer.',c.select('status','Decision',[['reviewing','Under review'],['clarification','Request clarification'],['approved','Approve for structuring'],['rejected','Reject']])+c.area('feedback','Reason or information needed'),'Save decision',v=>c.api('/proposals/'+id,v));return true}
 if(a==='proposal-reply'){c.openForm('Add clarification','Reply to the review team.',c.area('reply','Your response'),'Send clarification',v=>c.api('/proposals/'+id,v));return true}
 if(a==='structure-proposal'){const p=data.find(p=>p.id===id);sessionStorage.setItem('cb_proposal',JSON.stringify(p));location.href='/app/projects?structure='+id;return true}
 if(a==='new-org'){c.openForm('Create an organisation','You’ll be its first named member.',c.input('name','Organisation name')+c.area('description','What does your organisation do?'),'Create workspace',async v=>{const r=await c.api('/organisations',v);location.href='/app/organisation?id='+r.id});return true}
 if(a==='member'){c.openForm('Add an existing member','Ask them to sign in to CivicBench first.',c.input('email','Their email','email')+c.select('role','Access',['member','manager']),'Add member',v=>c.api('/organisations/'+id+'/members',v));return true}
 if(a==='org-support'){c.openForm('Link organisation support','Use a confirmed project funding record.',c.input('fundingId','Funding record ID'),'Link record',v=>c.api('/organisations/'+id+'/support',v));return true}
 if(a==='share-cv'){shareForm('cv',selected());return true}if(a==='share-entry'){shareForm('contribution',[id]);return true}if(a==='share-recap'){shareForm('recap',recapData.entries.map(e=>e.id),{from:recapData.from,to:recapData.to,organisationId:recapData.organisationId});return true}
 if(a==='share-visibility'){c.openForm('Change sharing visibility','Making this private disables access for other people.',c.select('visibility','Visibility',[['private','Private'],['link','Anyone with the link'],['public','Public']])+c.check('consent','I confirm the chosen sharing visibility.'),'Save visibility',v=>c.api('/shares/'+id,v));return true}
 if(a==='affiliate'){const orgs=(await c.api('/organisations')).organisations;c.openForm('Include in an organisation’s recap','The record must also be publicly verifiable to appear in a shared organisation recap.',c.select('organisationId','Organisation',orgs.map(o=>[o.id,o.name]))+c.check('consent','I consent to featuring this contribution in the organisation’s recap.'),'Save choice',v=>c.api('/affiliations',{...v,credentialId:id}));return true}
 if(a==='recap-prev'||a==='recap-next'){recapStep=Math.max(0,Math.min(4,recapStep+(a==='recap-next'?1:-1)));renderRecap();return true}
 if(a==='copy-link'){await navigator.clipboard.writeText(el.dataset.url);c.toast('Link copied.');return true}if(a==='native-share'){const url=el.dataset.url;if(navigator.share)await navigator.share({title:'CivicBench contribution record',url});else{await navigator.clipboard.writeText(url);c.toast('Link copied. Paste it into WhatsApp, LinkedIn or another app.')}return true}
 if(a==='print-record'){window.print();return true}if(a==='download-card'){downloadCard();return true}
 }catch(err){c.toast(err.name==='AbortError'?'Sharing cancelled.':err.message);return true}return false;}
function downloadCard(){const d=recapData||data;if(!d||Array.isArray(d))throw new Error('Open a record first.');const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const x=canvas.getContext('2d');x.fillStyle='#0647ab';x.fillRect(0,0,1080,1350);x.fillStyle='#8fe3b5';x.beginPath();x.arc(980,150,280,0,Math.PI*2);x.fill();x.fillStyle='#fff';x.font='bold 40px Arial';x.fillText('CivicBench',70,100);x.font='bold 66px Arial';const text=recapData?slides(d)[recapStep]:[d.name||'Verified contribution','Contribution record',`${d.entries?.filter(e=>e.correction_status!=='revoked').length||0} verified contributions`];let y=370;for(const line of text){const words=String(line).split(' ');let row='';for(const w of words){if(x.measureText(row+w).width>900){x.fillText(row,70,y);y+=86;row=''}row+=w+' '}x.fillText(row,70,y);y+=110;x.font='40px Arial'}x.font='24px Arial';x.fillText('Generated '+new Date().toLocaleDateString('en-NG'),70,1200);const url=location.pathname.startsWith('/s/')?location.href:location.origin+'/credentials';x.font='20px Arial';for(let i=0;i<url.length;i+=72)x.fillText(url.slice(i,i+72),70,1250+(i/72)*30);canvas.toBlob(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CivicBench-'+(recapData?'Impact-Recap':'Contribution')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)})}

web/styles.css.content:
:root{--ink:#152d37;--navy:#163b49;--blue:#0047ab;--green:#00843d;--mint:#d9f0df;--paper:#f7f8f4;--line:#dfe5de;--muted:#617078;--white:#fff;--red:#a83b39;--amber:#825b1b;font-family:Inter,Segoe UI,Arial,sans-serif;color:var(--ink);background:var(--paper);font-synthesis:none;scroll-behavior:smooth}
*{box-sizing:border-box}body{margin:0}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}button,a,input,select,textarea{touch-action:manipulation}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.55}button:focus-visible,a:focus-visible{outline:3px solid var(--blue);outline-offset:4px}input:focus,select:focus,textarea:focus{outline:2px solid var(--blue);outline-offset:1px}button{border:0}h1,h2,h3,p{margin-top:0}h1,h2,h3{letter-spacing:-.04em}h1{font-size:clamp(2.8rem,5.5vw,5.3rem);line-height:1.03;font-weight:650}h2{font-size:clamp(1.8rem,3vw,2.7rem);line-height:1.12;font-weight:600}h3{font-size:1.25rem;font-weight:600}p{line-height:1.7}small,.muted{color:var(--muted)}.wrap{max-width:1240px;margin:auto;padding:0 36px}.site-header{border-bottom:1px solid var(--line);background:rgba(247,248,244,.96);position:sticky;top:0;z-index:15}.nav{height:86px;display:flex;align-items:center;gap:32px}.brand{display:flex;align-items:center;gap:10px;font-size:1.35rem;font-weight:750;letter-spacing:-.04em;white-space:nowrap}.brand img{width:38px;height:38px;object-fit:contain}.nav-links{display:flex;align-items:center;gap:26px;margin-left:auto;font-size:.88rem}.nav-links a:hover,.footer a:hover{text-decoration:underline}.button,.button-secondary,.button-quiet{display:inline-flex;justify-content:center;align-items:center;gap:12px;padding:13px 20px;border-radius:7px;font-size:.88rem;font-weight:600;line-height:1.25;background:var(--navy);color:white;text-align:center}.button-secondary{background:transparent;border:1px solid #bac7bf;color:var(--ink)}.button-quiet{background:var(--mint);color:#244731}.button-danger{background:var(--red);color:white}.button.small,.button-secondary.small{padding:8px 12px;font-size:.78rem}.arrow{font-size:1.15rem}.eyebrow{display:flex;align-items:center;gap:9px;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.14em;color:#48715c;margin-bottom:24px}.dot{width:7px;height:7px;border-radius:50%;background:var(--green);display:inline-block}.hero{padding:82px 0 78px;display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center}.hero h1 em{font-style:normal;color:var(--green)}.hero .lead{font-size:1.08rem;max-width:525px;color:var(--muted);margin:26px 0 30px}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.hero-note{font-size:.78rem;margin-top:20px;color:var(--muted)}.diagram{position:relative;padding:32px;background:#e9efe7;border:1px solid #d2ded0;border-radius:18px;box-shadow:0 20px 50px #1233270b}.diagram-title{font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;display:flex;justify-content:space-between;color:#5e7464;margin-bottom:25px}.need-card{background:white;border:1px solid #d5e0d4;border-radius:10px;padding:22px;box-shadow:0 5px 15px #26493606}.need-card h3{margin:13px 0 8px;font-size:1.3rem}.need-card p{font-size:.84rem;color:var(--muted);margin:0}.badge{display:inline-flex;align-items:center;gap:6px;padding:5px 10px;border-radius:5px;background:#e6efea;color:#315e47;font-size:.68rem;font-weight:650;line-height:1.3;letter-spacing:.01em}.badge.blue{background:#e7eef9;color:#345784}.badge.amber{background:#fff0d9;color:var(--amber)}.badge.red{background:#fae9e7;color:var(--red)}.badge.gray{background:#edf0ee;color:#617078}.branch{height:27px;width:1px;background:#a9bcaa;margin:auto}.resource-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.resource-box{padding:16px;background:#f7fbf4;border:1px solid #cbdccc;border-radius:8px;font-size:.87rem}.resource-box small{display:block;font-size:.71rem;margin-top:7px}.verification{padding:15px 18px;background:var(--navy);color:white;border-radius:8px;font-size:.85rem;display:flex;justify-content:space-between}.outcome-mini{margin-top:15px;padding:16px;background:white;border:1px solid var(--line);border-radius:8px;display:grid;grid-template-columns:1fr 1fr;gap:20px}.outcome-mini small{font-size:.66rem;text-transform:uppercase;letter-spacing:.09em}.outcome-mini strong{display:block;font-size:.83rem;margin-top:7px}.principles{border-top:1px solid var(--line);border-bottom:1px solid var(--line);display:grid;grid-template-columns:repeat(3,1fr);padding:25px 0;gap:30px}.principle{display:flex;gap:12px;align-items:center;font-size:.82rem}.check{border:1px solid #adc8b3;width:23px;height:23px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;color:var(--green);flex-shrink:0}.section{padding:78px 0}.section-head{display:flex;justify-content:space-between;align-items:flex-end;gap:30px;margin-bottom:34px}.section-head h2{margin-bottom:0;max-width:600px}.section-head p{max-width:350px;font-size:.9rem;color:var(--muted);margin-bottom:0}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border:1px solid var(--line);border-radius:12px;overflow:hidden}.step{padding:27px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:white}.step:nth-child(3n){border-right:0}.step:nth-child(n+4){border-bottom:0}.step-number{font-size:.74rem;color:var(--green);font-weight:650;margin-bottom:28px}.step h3{margin-bottom:10px}.step p{font-size:.85rem;color:var(--muted);margin-bottom:0}.dark-section{background:var(--navy);color:white}.dark-section .eyebrow{color:#aed9b8}.dark-section p{color:#c3d3d5}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:40px}.example-box{border:1px solid #5b7881;border-radius:12px;padding:30px;background:#214855}.example-box .eyebrow{margin-bottom:30px}.example-box .result-row{padding:16px 0;border-top:1px solid #55717b}.result-row small{color:#b8d1d0;font-size:.7rem;text-transform:uppercase;letter-spacing:.08em}.result-row p{margin:7px 0 0;color:white;font-size:1rem}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:26px;border:1px solid var(--line);border-radius:10px;background:white}.card h3{margin:18px 0 10px}.card p{font-size:.86rem;color:var(--muted)}.card-link:hover{border-color:#91ac96;box-shadow:0 8px 20px #163b4910}.empty{padding:45px;border:1px dashed #becdc0;border-radius:12px;background:#f0f4ed;text-align:center}.empty h3{font-size:1.35rem;margin-bottom:10px}.empty p{max-width:530px;margin:0 auto;color:var(--muted);font-size:.9rem}.empty .button{margin-top:20px}.cta{display:flex;justify-content:space-between;align-items:center;gap:25px;padding:38px;border:1px solid #c6dac7;background:var(--mint);border-radius:12px}.cta h2{font-size:2rem;max-width:650px;margin-bottom:12px}.cta p{margin-bottom:0;max-width:600px;font-size:.88rem;color:#496554}.footer{border-top:1px solid var(--line);padding:36px 0}.footer-top{display:flex;justify-content:space-between;align-items:center}.footer-links{display:flex;gap:22px;font-size:.82rem}.footer-bottom{display:flex;justify-content:space-between;gap:20px;margin-top:30px;color:var(--muted);font-size:.72rem}.page-hero{padding:55px 0 35px}.page-hero h1{font-size:3rem;max-width:800px;margin-bottom:18px}.page-hero p{color:var(--muted);max-width:700px}.filter-bar{display:flex;gap:15px;align-items:center;margin-bottom:25px}.filter-bar input{max-width:380px}.timeline{display:grid;grid-template-columns:150px 1fr;gap:25px;padding:28px 0;border-top:1px solid var(--line)}.timeline time{font-size:.82rem;color:var(--green);font-weight:600;padding-top:4px}.timeline h3{margin-bottom:8px}.timeline p{font-size:.86rem;color:var(--muted);margin:0}.notice{padding:16px 20px;border:1px solid #e1d4b7;background:#fbf6e9;color:#725a26;border-radius:8px;font-size:.86rem;line-height:1.6;margin-bottom:25px}.notice.blue{background:#edf2f9;border-color:#c9d7eb;color:#345784}.notice.error{background:#fcecea;border-color:#e7bfba;color:var(--red)}.pill-tabs{display:flex;gap:7px;margin-bottom:24px;overflow:auto;padding-bottom:3px}.pill-tabs button{padding:10px 15px;background:#e9eeea;color:var(--muted);border-radius:7px;white-space:nowrap;font-size:.85rem}.pill-tabs button.active{background:var(--navy);color:white}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:22px}