export const NEED_FIELDS = [
  ['problem', 'Problem statement and evidence', 'What needs solving, and how do we know?'],
  ['audience', 'Affected place or audience', 'Who or where is affected?'],
  ['outcome', 'Public benefit and measurable outcome', 'What change would count as success?'],
  ['proposer', 'Proposer or source', 'Who identified the need?'],
  ['steward', 'Named steward', 'Who owns follow-through?'],
  ['scope', 'Initial scope and possible tasks', 'Bounded work that contributors can safely do.'],
  ['resources', 'Resources needed', 'Money, materials, or explicitly none.'],
  ['permissions', 'Permissions required', 'Authority and permissions, or why none are needed.'],
  ['safety', 'Safety and privacy checks', 'Risks, consent, and protection of personal data.'],
  ['evidence', 'Evidence standard and review approach', 'What proof and independent review are required?'],
  ['targetDate', 'Target date', 'When should this project finish?'],
  ['dissemination', 'Publication and dissemination plan', 'Who receives the result, and through which channels?'],
];
export const EXECUTION = ['proposed', 'screening', 'rejected', 'structured', 'active', 'completed', 'closed'];
export const IMPACT = ['not yet assessed', 'pending', 'partly resolved', 'resolved', 'unresolved'];
export const ELIGIBILITY = ['publicBenefit', 'lawfulAuthority', 'privacyConsent', 'contributorSafety', 'clearDeliverable', 'independentReview'];
export const WINDOW_MS = 72 * 60 * 60 * 1000;
export class Problem extends Error { constructor(status, message) { super(message); this.status = status; } }
export function requireThat(ok, message, status = 422) { if (!ok) throw new Problem(status, message); }
export function text(value, name, max = 6000) { requireThat(typeof value === 'string' && value.trim().length > 0 && value.trim().length <= max, `${name} is required (up to ${max} characters).`); return value.trim(); }
export function integer(value, name, min = 0) { requireThat(Number.isSafeInteger(value) && value >= min, `${name} must be a whole number of at least ${min}.`); return value; }
export function date(value, name) { const parsed=new Date(String(value)+'T00:00:00Z'); requireThat(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0,10) === value, `${name} must be a valid date.`); return value; }
export function validateNeed(input) {
  const record = Object.fromEntries(NEED_FIELDS.map(([key,label]) => [key, key === 'targetDate' ? date(input[key], label) : text(input[key], label)]));
  record.title = text(input.title, 'Project title', 180);
  record.stewardId = text(String(input.stewardId || ''), 'Steward account ID', 100);
  record.closingRule = text(input.closingRule, 'Closing rule');
  return record;
}
export function canMove(from, to) {
  return ({proposed:['screening'], screening:['structured','rejected'], structured:['active','closed'], active:['completed','closed'], completed:['closed'], rejected:[], closed:[]}[from] || []).includes(to);
}
export function validateScreening(input) {
  requireThat(['structured','rejected','clarification'].includes(input.decision), 'Choose a screening decision.');
  text(input.reason, 'Screening reason');
  if (input.decision === 'structured') requireThat(ELIGIBILITY.every(key => input.checks?.[key] === true), 'All six eligibility checks must pass.');
}
export function independent(reviewerId, contribution, funderIds = []) {
  requireThat(String(reviewerId) !== String(contribution.contributor_id) && !funderIds.map(String).includes(String(reviewerId)), 'You cannot review your own work or a project you fund.', 403);
}
export function canFinalize(contribution, reviewCount, openDisputes, now = Date.now()) {
  requireThat(contribution.status === 'acceptance', 'This contribution is not awaiting acceptance.');
  requireThat(reviewCount >= contribution.reviews_required, 'Independent approval is still required.');
  requireThat(openDisputes === 0, 'Resolve the dispute before finalising.');
  requireThat(Number.isFinite(Date.parse(contribution.acceptance_due)) && now >= Date.parse(contribution.acceptance_due), 'The 72-hour acceptance window is still open.');
}
export function kobo(value) {
  const raw = String(value).trim();
  requireThat(/^\d+(\.\d{1,2})?$/.test(raw), 'Enter a non-negative amount with up to two decimal places.');
  const [whole, fraction = ''] = raw.split('.');
  return integer(Number(whole) * 100 + Number(fraction.padEnd(2, '0')), 'Amount in kobo');
}
export function money(value) { return new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:2}).format(value / 100); }
export function safePublicProject(row) {
  return {id:row.id,title:row.title,audience:row.audience,outcome:row.outcome,steward:row.steward,target_date:row.target_date,execution_status:row.execution_status,impact_status:row.impact_status,completion_record:row.completion_record,impact_evidence:row.impact_evidence,outstanding_need:row.outstanding_need,next_impact_review_date:row.next_impact_review_date,closing_rule:row.closing_rule,public_summary:row.public_summary,dissemination_record:row.dissemination_record,updated_at:row.updated_at};
}

