import {Problem,requireThat,text,integer,date,validateNeed,validateScreening,canMove,independent,canFinalize,IMPACT,WINDOW_MS,safePublicProject} from './model.mjs';
import {community} from './community.mjs';
import {sessionToken,identityFetch} from './identity.mjs';
import {databaseEvidence} from './storage.mjs';
const id = () => crypto.randomUUID();
const now = () => new Date().toISOString();
const json = (data,status=200) => new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const pick = (row,keys) => Object.fromEntries(keys.map(key=>[key,row[key]]));
const list = async (db,sql,...args) => (await db.prepare(sql).bind(...args).all()).results || [];
const one = (db,sql,...args) => db.prepare(sql).bind(...args).first();
const run = (db,sql,...args) => db.prepare(sql).bind(...args).run();
const exists = (row,label) => {requireThat(row,`${label} not found.`,404);return row;};
async function body(request) { requireThat(Number(request.headers.get('content-length')||0)<80000,'Request is too large.',413); const raw=await request.text();requireThat(raw.length<80000,'Request is too large.',413);try{return JSON.parse(raw);}catch{throw new Problem(400,'Invalid JSON.');} }
async function identity(request,env,fetcher) {
  const auth='Bearer '+sessionToken(request);
  requireThat(/^Bearer [A-Za-z0-9_.-]+$/.test(auth),'Sign in to continue.',401);
  const response=await identityFetch(env,'https://civicbench-api.akintomiwaposi.workers.dev/api/me',{headers:{Authorization:auth},redirect:'manual'},fetcher);
  requireThat(response.ok,'Your session has expired. Sign in again.',401);
  const {user}=await response.json();
  requireThat(user && user.id != null && !String(user.email).toLowerCase().endsWith('@demo.com'),'This account is not available for the controlled service.',403);
  const userId=String(user.id);
  await run(env.CB_DB,'INSERT INTO cb_accounts VALUES (?,?,?) ON CONFLICT(user_id) DO UPDATE SET name=excluded.name,email=excluded.email',userId,String(user.name||'Contributor').slice(0,180),String(user.email||'').toLowerCase());
  const roles=(await list(env.CB_DB,'SELECT role FROM cb_roles WHERE user_id=?',userId)).map(r=>r.role);
  const admins=String(env.CB_COORDINATOR_IDS||'').split(',').map(s=>s.trim()).filter(Boolean);
  if(admins.includes(userId)) roles.push('coordinator');
  return {id:userId,name:user.name,roles:[...new Set([...roles,'contributor'])]};
}
const staff = user => requireThat(user.roles.includes('coordinator'),'Coordinator access is required.',403);
const role = (user,name) => requireThat(user.roles.includes(name)||user.roles.includes('coordinator'),`${name} access is required.`,403);
async function projectAccess(db,user,projectId) {
 const p=exists(await one(db,'SELECT * FROM cb_projects WHERE id=?',projectId),'Project');
 if(user.roles.includes('coordinator')||p.steward_id===user.id) return p;
 const assigned=await one(db,'SELECT 1 FROM cb_tasks t JOIN cb_assignments a ON a.task_id=t.id WHERE t.project_id=? AND a.contributor_id=?',projectId,user.id);
 const funded=await one(db,'SELECT 1 FROM cb_funding WHERE project_id=? AND funder_id=?',projectId,user.id);
 const reviewing=await one(db,'SELECT 1 FROM cb_tasks t JOIN cb_contributions c ON c.task_id=t.id JOIN cb_review_assignments a ON a.contribution_id=c.id WHERE t.project_id=? AND a.reviewer_id=?',projectId,user.id);
 requireThat(assigned||funded||reviewing,'You are not assigned to this project.',403);return p;
}
async function manage(db,user,projectId){const p=await projectAccess(db,user,projectId);requireThat(user.roles.includes('coordinator')||p.steward_id===user.id,'Only the coordinator or named steward can manage this project.',403);return p;}
async function contributionAccess(db,user,contributionId) {
 const c=exists(await one(db,'SELECT c.*,t.project_id,t.mode,t.reward_kobo,t.reviews_required,t.acceptance_by,t.rubric,t.title AS task_title FROM cb_contributions c JOIN cb_tasks t ON t.id=c.task_id WHERE c.id=?',contributionId),'Contribution');
 await projectAccess(db,user,c.project_id);return c;
}
async function projectDetail(db,user,p) {
 const manager=user.roles.includes('coordinator')||p.steward_id===user.id;
 const tasks=await list(db,'SELECT * FROM cb_tasks WHERE project_id=? ORDER BY created_at',p.id);
 const assignments=await list(db,'SELECT a.* FROM cb_assignments a JOIN cb_tasks t ON t.id=a.task_id WHERE t.project_id=?',p.id);
 const contributions=await list(db,'SELECT c.* FROM cb_contributions c JOIN cb_tasks t ON t.id=c.task_id WHERE t.project_id=?',p.id);
 const reviewAssignments=await list(db,'SELECT a.* FROM cb_review_assignments a JOIN cb_contributions c ON c.id=a.contribution_id JOIN cb_tasks t ON t.id=c.task_id WHERE t.project_id=?',p.id);
 const reviewerIds=new Set(reviewAssignments.filter(a=>a.reviewer_id===user.id).map(a=>a.contribution_id));
 const visibleContributions=contributions.filter(c=>manager||c.contributor_id===user.id||reviewerIds.has(c.id)||tasks.some(t=>t.id===c.task_id&&t.acceptance_by===user.id));
 const visibleIds=new Set(visibleContributions.map(c=>c.id));
 const evidence=(await list(db,'SELECT e.* FROM cb_evidence e JOIN cb_contributions c ON c.id=e.contribution_id JOIN cb_tasks t ON t.id=c.task_id WHERE t.project_id=?',p.id)).filter(e=>visibleIds.has(e.contribution_id));
 const reviews=(await list(db,'SELECT r.* FROM cb_reviews r JOIN cb_contributions c ON c.id=r.contribution_id JOIN cb_tasks t ON t.id=c.task_id WHERE t.project_id=?',p.id)).filter(r=>visibleIds.has(r.contribution_id));
 return {project:p,manager,tasks,assignments:assignments.filter(a=>manager||a.contributor_id===user.id),contributions:visibleContributions,evidence,reviews,reviewAssignments:reviewAssignments.filter(a=>manager||a.reviewer_id===user.id),
  funding:manager||user.roles.includes('funder')?await list(db,'SELECT * FROM cb_funding WHERE project_id=?',p.id):[],
  costs:manager?await list(db,'SELECT * FROM cb_costs WHERE project_id=?',p.id):[],
  decisions:manager?await list(db,'SELECT * FROM cb_decisions WHERE project_id=? ORDER BY created_at',p.id):[],
  corrections:await list(db,'SELECT summary,corrected_at FROM cb_corrections WHERE project_id=?',p.id),
  disputes:(await list(db,'SELECT d.* FROM cb_disputes d JOIN cb_contributions c ON c.id=d.contribution_id JOIN cb_tasks t ON t.id=c.task_id WHERE t.project_id=?',p.id)).filter(d=>visibleIds.has(d.contribution_id)),
  credentials:(await list(db,'SELECT * FROM cb_credentials WHERE project_id=?',p.id)).filter(c=>manager||c.contributor_id===user.id),
  payments:(await list(db,'SELECT pay.* FROM cb_payments pay JOIN cb_contributions c ON c.id=pay.contribution_id JOIN cb_tasks t ON t.id=c.task_id WHERE t.project_id=?',p.id)).filter(pay=>manager||visibleContributions.some(c=>c.id===pay.contribution_id&&c.contributor_id===user.id))};
}
export async function handle(request,env,fetcher=fetch) {
 try {
  const url=new URL(request.url);const path=url.pathname.replace(/^\/api\/v2/,''); const method=request.method;const db=env.CB_DB;
  if(method!=='GET'&&method!=='HEAD') {const origin=request.headers.get('Origin');requireThat(!origin||origin===url.origin,'Cross-origin writes are not allowed.',403);}
  const evidenceLimit=env.CB_EVIDENCE?5*1024*1024:512*1024;
  if(db&&!env.CB_EVIDENCE)env={...env,CB_EVIDENCE:databaseEvidence(db)};
  if(path==='/health') return json({version:'2.1',configured:!!db,evidenceStorage:!!env.CB_EVIDENCE,maxEvidenceBytes:evidenceLimit,publicIntake:!!db,pooledFunding:false});
  if(!db){if(method==='GET'&&path==='/public/projects') return json({projects:[],setupPending:true});throw new Problem(503,'The controlled workspace is being prepared. Public intake remains closed.');}
  if(path.startsWith('/public/')){const response=await community(request,env,path,null);if(response)return response;}
  if(method==='GET'&&path==='/public/projects') return json({projects:(await list(db,'SELECT * FROM cb_projects WHERE published=1 ORDER BY updated_at DESC')).map(safePublicProject)});
  let m=path.match(/^\/public\/projects\/([^/]+)$/);
  if(method==='GET'&&m){const p=exists(await one(db,'SELECT * FROM cb_projects WHERE id=? AND published=1',m[1]),'Published project');return json({project:safePublicProject(p),corrections:await list(db,'SELECT summary,corrected_at FROM cb_corrections WHERE project_id=? ORDER BY corrected_at',p.id)});}
  m=path.match(/^\/public\/credentials\/([^/]+)$/);
  if(method==='GET'&&m){const c=exists(await one(db,'SELECT c.id,c.decision,c.issued_at,c.correction_status,c.correction_reason,p.title AS project_title,t.title AS task_title FROM cb_credentials c JOIN cb_projects p ON p.id=c.project_id JOIN cb_tasks t ON t.id=c.task_id WHERE c.id=? AND c.visibility=\'public\'',m[1]),'Public credential');return json({credential:c});}
  const user=await identity(request,env,fetcher);
  if(env.setAuditActor)env.setAuditActor(user.id);
  const extra=await community(request,env,path,user);if(extra)return extra;
  if(method==='GET'&&path==='/me')return json({user});
  if(method==='GET'&&path==='/projects') {
    const all=await list(db,'SELECT * FROM cb_projects ORDER BY updated_at DESC');const projects=[];
    for(const p of all){try{await projectAccess(db,user,p.id);projects.push(p);}catch(e){if(e.status!==403)throw e;}}return json({projects});
  }
  if(method==='POST'&&path==='/projects') {
    staff(user);const input=await body(request);const n=validateNeed(input);const pid=id();
    if(input.proposalId){const proposal=await one(db,"SELECT * FROM cb_proposals WHERE id=? AND status='approved' AND project_id IS NULL",input.proposalId);requireThat(proposal,'Choose an approved proposal that has not been structured.');}
    if(input.previousId){const prev=exists(await one(db,'SELECT execution_status FROM cb_projects WHERE id=?',input.previousId),'Previous need');requireThat(prev.execution_status==='rejected','Only a rejected need can be resubmitted as a linked record.');}
    const create=db.prepare('INSERT INTO cb_projects (id,title,problem,audience,outcome,proposer,steward,steward_id,scope,resources,permissions,safety,evidence,target_date,dissemination,closing_rule,previous_id,created_at,updated_at,proposal_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(pid,n.title,n.problem,n.audience,n.outcome,n.proposer,n.steward,n.stewardId,n.scope,n.resources,n.permissions,n.safety,n.evidence,n.targetDate,n.dissemination,n.closingRule,input.previousId||null,now(),now(),input.proposalId||null);await db.batch([create,...(input.proposalId?[db.prepare('UPDATE cb_proposals SET project_id=?,updated_at=? WHERE id=?').bind(pid,now(),input.proposalId)]:[])]);return json({id:pid},201);
  }
  m=path.match(/^\/projects\/([^/]+)(?:\/(.+))?$/);
  if(m) {
   const pid=m[1],action=m[2];const p=await projectAccess(db,user,pid);
   if(method==='GET'&&!action)return json(await projectDetail(db,user,p));
   if(method==='POST'&&action==='screen') {
    staff(user);const input=await body(request);validateScreening(input);requireThat(['proposed','screening'].includes(p.execution_status),'Screening is final for this record.');
    const status=input.decision==='clarification'?'screening':input.decision;
    await db.batch([db.prepare('INSERT INTO cb_decisions VALUES (?,?,?,?,?,?,?)').bind(id(),pid,user.id,input.decision,input.reason,JSON.stringify(input.checks||{}),now()),db.prepare('UPDATE cb_projects SET execution_status=?,updated_at=? WHERE id=?').bind(status,now(),pid)]);return json({ok:true});
   }
   if(method==='POST'&&action==='outcome') {
    await manage(db,user,pid);const input=await body(request);requireThat(!['rejected','closed'].includes(p.execution_status),'This project record is terminal.');
    requireThat(IMPACT.includes(input.impactStatus),'Choose an impact status.');text(input.impactEvidence,'Impact evidence');text(input.outstandingNeed,'Outstanding need');date(input.nextReview,'Next impact review date');
    const status=input.executionStatus||p.execution_status;requireThat(status===p.execution_status||canMove(p.execution_status,status),'Invalid execution transition.');
    if(status==='completed') {text(input.completionRecord,'Completion record');const unfinished=await one(db,'SELECT COUNT(*) AS n FROM cb_tasks WHERE project_id=? AND status NOT IN (\'accepted\',\'closed\')',pid);const count=await one(db,'SELECT COUNT(*) AS n FROM cb_tasks WHERE project_id=?',pid);requireThat(count.n>0&&unfinished.n===0,'All tasks must be verified and accepted or closed before completion.');const revoked=await one(db,'SELECT COUNT(*) AS n FROM cb_credentials WHERE project_id=? AND correction_status=\'revoked\'',pid);requireThat(revoked.n===0,'Correct revoked contribution records before completion.');}
    if(status==='closed') text(input.completionRecord,'Closure reason');
    await run(db,'UPDATE cb_projects SET execution_status=?,impact_status=?,impact_evidence=?,outstanding_need=?,next_impact_review_date=?,completion_record=?,dissemination_record=?,closed_at=?,updated_at=? WHERE id=?',status,input.impactStatus,input.impactEvidence,input.outstandingNeed,input.nextReview,input.completionRecord||p.completion_record,input.disseminationRecord||p.dissemination_record,status==='closed'?now():p.closed_at,now(),pid);return json({ok:true});
   }
   if(method==='POST'&&action==='publish') {
    staff(user);const input=await body(request);requireThat(['structured','active','completed','closed'].includes(p.execution_status),'Only screened projects can be published.');text(input.publicSummary,'Public summary');requireThat(input.privacyChecked===true,'Confirm the public record has been checked for privacy.');
    if(p.execution_status==='completed'){const pending=await one(db,'SELECT COUNT(*) AS n FROM cb_contributions c JOIN cb_tasks t ON t.id=c.task_id WHERE t.project_id=? AND c.status!=\'accepted\'',pid);requireThat(pending.n===0,'Results cannot be published before independent approval and acceptance.');text(p.dissemination_record,'Dissemination record');}
    await run(db,'UPDATE cb_projects SET published=1,public_summary=?,updated_at=? WHERE id=?',input.publicSummary,now(),pid);return json({ok:true});
   }
   if(method==='POST'&&action==='correction'){staff(user);const input=await body(request);await run(db,'INSERT INTO cb_corrections VALUES (?,?,?,?,?)',id(),pid,text(input.summary,'Correction summary'),now(),user.id);return json({ok:true});}
   if(method==='POST'&&action==='funding') {
    await manage(db,user,pid);requireThat(['structured','active'].includes(p.execution_status),'Screen the project before funding.');const input=await body(request);requireThat(['money','material'].includes(input.type),'Choose money or material.');requireThat(['pledged','committed','held','released','refunded'].includes(input.status),'Choose a funding status.');
    const amount=input.type==='money'?integer(input.amountKobo,'Amount in kobo',1):0;
    if(input.type==='material'){text(input.materialDescription,'Material description');integer(input.quantity,'Quantity',1);text(input.unit,'Unit');}
    await run(db,'INSERT INTO cb_funding VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)',id(),pid,text(String(input.funderId||''),'Funder account ID',100),text(input.funderName,'Funder name',180),input.type,amount,input.materialDescription||'',input.quantity||0,input.unit||'',input.status,text(input.agreementRef,'Agreement reference'),text(input.paymentRoute,'Payment or delivery route'),input.deliveryRecord||'',now());return json({ok:true},201);
   }
   if(method==='POST'&&action==='costs') {
    await manage(db,user,pid);const input=await body(request);await run(db,'INSERT INTO cb_costs VALUES (?,?,?,?,?,?,?,?,?)',id(),pid,text(input.category,'Cost category',100),integer(input.minutes,'Minutes'),integer(input.rateKobo,'Shadow rate per hour in kobo'),integer(input.directKobo,'Direct cost in kobo'),input.donated?1:0,text(input.note,'Cost note'),now());return json({ok:true},201);
   }
   if(method==='POST'&&action==='tasks') {
    await manage(db,user,pid);requireThat(['structured','active'].includes(p.execution_status),'Screen and structure this need before creating tasks.');const input=await body(request);requireThat(['paid','volunteer'].includes(input.mode),'Choose paid or volunteer terms.');const reward=input.mode==='paid'?integer(input.rewardKobo,'Reward in kobo',1):0;
    const tid=id();integer(input.capacity||1,'Capacity',1);requireThat((input.capacity||1)<=20,'Split larger work into bounded tasks.');requireThat([1,2].includes(input.reviewsRequired),'Choose one or two independent reviews.');
    await run(db,'INSERT INTO cb_tasks (id,project_id,title,brief,rubric,evidence_standard,mode,reward_kobo,deadline,capacity,reviews_required,terms,steward_signoff,funder_signoff,acceptance_by,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',tid,pid,text(input.title,'Task title',180),text(input.brief,'Task brief'),text(input.rubric,'Rubric'),text(input.evidenceStandard,'Evidence standard'),input.mode,reward,date(input.deadline,'Task deadline'),input.capacity||1,input.reviewsRequired,text(input.terms,'Assignment terms'),text(input.stewardSignoff,'Steward sign-off'),input.funderSignoff||'',input.mode==='paid'?text(String(input.acceptanceBy||''),'Funder acceptance account ID'):p.steward_id,now());return json({id:tid},201);
   }
  }
  m=path.match(/^\/tasks\/([^/]+)\/(.+)$/);
  if(m&&method==='POST') {
   const t=exists(await one(db,'SELECT * FROM cb_tasks WHERE id=?',m[1]),'Task');await projectAccess(db,user,t.project_id);const action=m[2];const input=await body(request);
   if(action==='allocate'){await manage(db,user,t.project_id);requireThat(t.mode==='paid','Volunteer tasks do not need money allocations.');await run(db,'INSERT INTO cb_allocations VALUES (?,?,?)',t.id,text(input.fundingId,'Funding ID'),integer(input.amountKobo,'Allocation in kobo',1));return json({ok:true});}
   if(action==='open'){await manage(db,user,t.project_id);requireThat(t.status==='draft','Only draft tasks can be opened.');await run(db,'UPDATE cb_tasks SET status=\'open\' WHERE id=? AND status=\'draft\'',t.id);return json({ok:true});}
   if(action==='assign'){await manage(db,user,t.project_id);const uid=text(String(input.contributorId||''),'Contributor account ID');const r=await one(db,'SELECT 1 FROM cb_roles WHERE user_id=? AND role=\'contributor\'',uid);requireThat(r,'Assign a vetted contributor account first.');await db.batch([db.prepare('INSERT INTO cb_assignments VALUES (?,?,?,?,?)').bind(t.id,uid,now(),null,null),db.prepare('UPDATE cb_tasks SET status=\'claimed\' WHERE id=?').bind(t.id)]);return json({ok:true});}
   if(action==='agree'){requireThat(input.agree===true,'Explicitly accept the stated paid or volunteer terms.');const result=await run(db,'UPDATE cb_assignments SET agreed_at=?,agreed_terms=? WHERE task_id=? AND contributor_id=? AND agreed_at IS NULL',now(),t.terms,t.id,user.id);requireThat(result.meta?.changes===1,'You are not awaiting agreement on this task.');return json({ok:true});}
   if(action==='submit') {
    const a=exists(await one(db,'SELECT * FROM cb_assignments WHERE task_id=? AND contributor_id=?',t.id,user.id),'Your assignment');requireThat(a.agreed_at,'Accept your assignment terms before starting.');requireThat(!['accepted','closed'].includes(t.status),'This task is closed.');text(input.submission,'Contribution and method');
    const old=await one(db,'SELECT * FROM cb_contributions WHERE task_id=? AND contributor_id=?',t.id,user.id);
