    if(old){const reviews=await list(db,'SELECT * FROM cb_reviews WHERE contribution_id=?',old.id);await db.batch([db.prepare('INSERT INTO cb_rework_history VALUES (?,?,?,?,?)').bind(id(),old.id,old.submission,JSON.stringify(reviews),now()),db.prepare('DELETE FROM cb_reviews WHERE contribution_id=?').bind(old.id),db.prepare('DELETE FROM cb_review_assignments WHERE contribution_id=?').bind(old.id),db.prepare('UPDATE cb_contributions SET submission=?,status=\'submitted\',submitted_at=?,acceptance_due=NULL WHERE id=?').bind(input.submission,now(),old.id),db.prepare('UPDATE cb_tasks SET status=\'submitted\' WHERE id=?').bind(t.id)]);return json({id:old.id});}
    const cid=id();await db.batch([db.prepare('INSERT INTO cb_contributions (id,task_id,contributor_id,submission,submitted_at) VALUES (?,?,?,?,?)').bind(cid,t.id,user.id,input.submission,now()),db.prepare('UPDATE cb_tasks SET status=\'submitted\' WHERE id=?').bind(t.id)]);return json({id:cid},201);
   }
  }
  m=path.match(/^\/contributions\/([^/]+)\/(.+)$/);
  if(m) {
   const c=await contributionAccess(db,user,m[1]);const action=m[2];
   if(method==='POST'&&action==='evidence') {
    requireThat(c.contributor_id===user.id&&['submitted','rejected'].includes(c.status),'Only the contributor can upload evidence before review.',403);requireThat(env.CB_EVIDENCE,'Evidence storage is not configured.',503);
    const size=integer(Number(request.headers.get('x-file-size')||request.headers.get('content-length')),'File size',1);requireThat(size<=evidenceLimit,`Keep evidence files under ${evidenceLimit===512*1024?'512 KB':'5 MB'}.`,413);const mime=request.headers.get('content-type')?.split(';')[0];requireThat(['application/pdf','image/png','image/jpeg','text/plain'].includes(mime),'Upload a PDF, PNG, JPEG, or text file.');
    const data=await request.arrayBuffer();requireThat(data.byteLength===size,'File length did not match.');const eid=id(),key=`evidence/${c.id}/${eid}`;const filename=text(decodeURIComponent(request.headers.get('x-filename')||'evidence'),'File name',180).replace(/[\r\n"\\/]/g,'_');
    await env.CB_EVIDENCE.put(key,data,{httpMetadata:{contentType:mime}});try{await run(db,'INSERT INTO cb_evidence VALUES (?,?,?,?,?,?,?)',eid,c.id,key,filename,mime,size,now());}catch(e){await env.CB_EVIDENCE.delete(key);throw e;}return json({id:eid},201);
   }
   if(method==='POST'&&action==='assign-reviewer') {
    await manage(db,user,c.project_id);const input=await body(request);const uid=text(String(input.reviewerId||''),'Reviewer account ID');requireThat(await one(db,'SELECT 1 FROM cb_roles WHERE user_id=? AND role=\'reviewer\'',uid),'Choose a vetted reviewer.');independent(uid,c,(await list(db,'SELECT funder_id FROM cb_funding WHERE project_id=?',c.project_id)).map(f=>f.funder_id));
    requireThat(['submitted','under review'].includes(c.status),'This contribution is not awaiting review.');const proof=await one(db,'SELECT COUNT(*) AS n FROM cb_evidence WHERE contribution_id=?',c.id);requireThat(proof.n>0,'Upload evidence files before review assignment.');
    await db.batch([db.prepare('INSERT INTO cb_review_assignments VALUES (?,?,?)').bind(c.id,uid,now()),db.prepare('UPDATE cb_contributions SET status=\'under review\' WHERE id=?').bind(c.id),db.prepare('UPDATE cb_tasks SET status=\'under review\' WHERE id=?').bind(c.task_id)]);return json({ok:true});
   }
   if(method==='POST'&&action==='review') {
    role(user,'reviewer');const input=await body(request);requireThat(c.status==='under review','This contribution is not under review.');independent(user.id,c,(await list(db,'SELECT funder_id FROM cb_funding WHERE project_id=?',c.project_id)).map(f=>f.funder_id));requireThat(input.noConflict===true,'Declare your independence before reviewing.');
    requireThat(['approved','rejected'].includes(input.decision),'Choose approve or return for rework.');integer(input.accuracy,'Accuracy score');integer(input.publicValue,'Public value score');requireThat(input.accuracy<=100&&input.publicValue<=100,'Scores must be at most 100.');requireThat(input.decision!=='approved'||input.accuracyPassed===true,'A failed accuracy review cannot be overridden.');
    await run(db,'INSERT INTO cb_reviews VALUES (?,?,?,?,?,?,?,?,?,?,?)',id(),c.id,user.id,input.decision,input.accuracy,input.publicValue,text(input.comments,'Rubric assessment and method'),1,integer(input.feeKobo,'Flat review fee'),integer(input.minutes,'Review minutes'),now());
    const reviews=await list(db,'SELECT * FROM cb_reviews WHERE contribution_id=?',c.id);
    if(reviews.length>=c.reviews_required&&reviews.some(r=>r.decision==='rejected')){const disagreement=reviews.some(r=>r.decision==='approved');await run(db,'UPDATE cb_contributions SET status=? WHERE id=?',disagreement?'disputed':'rejected',c.id);await run(db,'UPDATE cb_tasks SET status=? WHERE id=?',disagreement?'disputed':'rejected',c.task_id);if(disagreement)await run(db,'INSERT INTO cb_disputes (id,contribution_id,raised_by,reason,created_at) VALUES (?,?,?,?,?)',id(),c.id,user.id,'Independent reviewers disagree. Three-person panel required.',now());}
    else if(reviews.length>=c.reviews_required) await run(db,'UPDATE cb_contributions SET status=\'acceptance\',acceptance_due=? WHERE id=?',new Date(Date.now()+WINDOW_MS).toISOString(),c.id);
    return json({ok:true});
   }
   if(method==='POST'&&action==='dispute') {
    const input=await body(request);const participant=c.contributor_id===user.id||c.acceptance_by===user.id;requireThat(participant,'Only the contributor or acceptance owner can dispute this work.',403);
    requireThat(['acceptance','rejected'].includes(c.status),'This work is not in an acceptance or rework stage.');if(c.status==='acceptance')requireThat(Date.now()<=Date.parse(c.acceptance_due),'The acceptance contest window has ended.');
    await db.batch([db.prepare('INSERT INTO cb_disputes (id,contribution_id,raised_by,reason,created_at) VALUES (?,?,?,?,?)').bind(id(),c.id,user.id,text(input.reason,'Rubric-based dispute reason'),now()),db.prepare('UPDATE cb_contributions SET status=\'disputed\' WHERE id=?').bind(c.id),db.prepare('UPDATE cb_tasks SET status=\'disputed\' WHERE id=?').bind(c.task_id)]);return json({ok:true});
   }
   if(method==='POST'&&action==='resolve') {
    staff(user);const input=await body(request);requireThat(c.status==='disputed','This contribution is not disputed.');requireThat(Array.isArray(input.panelIds)&&input.panelIds.length===3&&new Set(input.panelIds).size===3,'A three-person panel is required.');
    const funders=(await list(db,'SELECT funder_id FROM cb_funding WHERE project_id=?',c.project_id)).map(f=>f.funder_id);
    for(const uid of input.panelIds){requireThat(await one(db,'SELECT 1 FROM cb_roles WHERE user_id=? AND role=\'reviewer\'',String(uid)),'Every panel member must be a vetted reviewer.');independent(String(uid),c,funders);}
    requireThat(['approved','rejected'].includes(input.decision),'Choose a panel decision.');requireThat(input.decision!=='approved'||input.accuracyPassed===true,'Independent accuracy approval remains required.');text(input.reason,'Panel rubric assessment');
    await db.batch([db.prepare('UPDATE cb_disputes SET status=\'resolved\',panel_json=?,decision=?,resolved_at=? WHERE contribution_id=? AND status=\'open\'').bind(JSON.stringify({members:input.panelIds,reason:input.reason,accuracyPassed:input.accuracyPassed}),input.decision,now(),c.id),db.prepare('UPDATE cb_contributions SET status=?,acceptance_due=? WHERE id=?').bind(input.decision==='approved'?'acceptance':'rejected',input.decision==='approved'?new Date(Date.now()+WINDOW_MS).toISOString():null,c.id),db.prepare('UPDATE cb_tasks SET status=? WHERE id=?').bind(input.decision==='approved'?'under review':'rejected',c.task_id)]);return json({ok:true});
   }
   if(method==='POST'&&action==='finalize') {
    await manage(db,user,c.project_id);const reviews=await list(db,'SELECT * FROM cb_reviews WHERE contribution_id=? AND decision=\'approved\'',c.id);const disputes=await one(db,'SELECT COUNT(*) AS n FROM cb_disputes WHERE contribution_id=? AND status=\'open\'',c.id);const panel=await one(db,'SELECT panel_json FROM cb_disputes WHERE contribution_id=? AND status=\'resolved\' AND decision=\'approved\' ORDER BY resolved_at DESC LIMIT 1',c.id);canFinalize(c,panel?c.reviews_required:reviews.length,disputes.n);
    const cid=id();await db.batch([db.prepare('INSERT INTO cb_credentials (id,contribution_id,contributor_id,project_id,task_id,verifier_id,issued_at) VALUES (?,?,?,?,?,?,?)').bind(cid,c.id,c.contributor_id,c.project_id,c.task_id,panel?JSON.parse(panel.panel_json).members.join(','):reviews.map(r=>r.reviewer_id).join(','),now()),db.prepare('UPDATE cb_contributions SET status=\'accepted\',accepted_at=? WHERE id=? AND status=\'acceptance\'').bind(now(),c.id)]);
    const task=await one(db,'SELECT capacity FROM cb_tasks WHERE id=?',c.task_id);const count=await one(db,'SELECT COUNT(*) AS n FROM cb_contributions WHERE task_id=? AND status=\'accepted\'',c.task_id);if(count.n===task.capacity)await run(db,'UPDATE cb_tasks SET status=\'accepted\' WHERE id=?',c.task_id);return json({credentialId:cid});
   }
   if(method==='POST'&&action==='payment') {
    staff(user);const input=await body(request);requireThat(c.status==='accepted'&&c.mode==='paid','Only accepted paid work has a payment record.');requireThat(input.alreadyPaid===true,'Record only an actual payment made through the agreed external route.');
    await run(db,'INSERT INTO cb_payments VALUES (?,?,?,?,?,?,?)',id(),c.id,c.reward_kobo,text(input.route,'Licensed provider or manual agreement'),text(input.reference,'External payment reference'),date(input.paidAt,'Payment date'),user.id);return json({ok:true});
   }
  }
  m=path.match(/^\/evidence\/([^/]+)$/);
  if(method==='GET'&&m) {
    const e=exists(await one(db,'SELECT * FROM cb_evidence WHERE id=?',m[1]),'Evidence');const c=await contributionAccess(db,user,e.contribution_id);const p=await projectAccess(db,user,c.project_id);const assigned=await one(db,'SELECT 1 FROM cb_review_assignments WHERE contribution_id=? AND reviewer_id=?',c.id,user.id);
    requireThat(user.roles.includes('coordinator')||p.steward_id===user.id||c.contributor_id===user.id||c.acceptance_by===user.id||assigned,'Evidence is private.',403);requireThat(env.CB_EVIDENCE,'Evidence storage is not configured.',503);const object=exists(await env.CB_EVIDENCE.get(e.object_key),'Stored evidence');return new Response(object.body,{headers:{'Content-Type':e.mime_type,'Content-Disposition':`attachment; filename="${e.filename}"`,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
  }
  m=path.match(/^\/credentials\/([^/]+)$/);
  if(method==='POST'&&m) {
    const c=exists(await one(db,'SELECT * FROM cb_credentials WHERE id=?',m[1]),'Credential');const input=await body(request);
    if(input.visibility){requireThat(c.contributor_id===user.id,'Only the contributor can choose public visibility.',403);requireThat(['private','public'].includes(input.visibility),'Choose visibility.');await run(db,'UPDATE cb_credentials SET visibility=? WHERE id=?',input.visibility,c.id);}
    else{staff(user);requireThat(['corrected','revoked'].includes(input.correctionStatus),'Choose correction or revocation.');await run(db,'UPDATE cb_credentials SET correction_status=?,correction_reason=? WHERE id=?',input.correctionStatus,text(input.reason,'Correction reason'),c.id);}return json({ok:true});
  }
  if(path==='/roles'&&method==='POST'){staff(user);const input=await body(request);requireThat(['steward','contributor','reviewer','funder'].includes(input.role),'Choose a controlled-service role.');await run(db,'INSERT OR IGNORE INTO cb_roles VALUES (?,?)',text(String(input.userId||''),'Existing account ID'),input.role);return json({ok:true});}
  if(path==='/gates'&&method==='GET'){return json({gates:await list(db,'SELECT * FROM cb_gate_decisions ORDER BY gate')});}
  if(path==='/gates'&&method==='POST'){staff(user);const input=await body(request);requireThat([1,2,3].includes(input.gate),'Choose a gate.');requireThat(['proceed','retest','redesign'].includes(input.decision),'Choose a decision.');await run(db,'INSERT INTO cb_gate_decisions VALUES (?,?,?,?,?) ON CONFLICT(gate) DO UPDATE SET decision=excluded.decision,evidence=excluded.evidence,actor_id=excluded.actor_id,recorded_at=excluded.recorded_at',input.gate,input.decision,text(input.evidence,'Measured evidence and decision rationale'),user.id,now());return json({ok:true});}
  throw new Problem(404,'This route is not available.');
 }catch(e){if(e instanceof Problem)return json({error:e.message},e.status);const message=String(e.message||'');if(/capacity is full|already allocated|Funding must|must pass|need full|must be assigned|conflict of interest|Assigned terms/.test(message))return json({error:message.replace(/^.*?: /,'')},409);if(/UNIQUE constraint/.test(message))return json({error:'This action was already recorded. Refresh to see the current state.'},409);console.error('CivicBench request failed:',e.name);return json({error:'The workspace could not complete this request. Please retry or contact your coordinator.'},500);}
}

