import {Problem,requireThat,text,date} from './model.mjs';
const uid=()=>crypto.randomUUID(),stamp=()=>new Date().toISOString();
const reply=(v,s=200)=>Response.json(v,{status:s,headers:{'Cache-Control':'no-store'}});
const all=async(db,sql,...a)=>(await db.prepare(sql).bind(...a).all()).results||[];
const first=(db,sql,...a)=>db.prepare(sql).bind(...a).first();
const run=(db,sql,...a)=>db.prepare(sql).bind(...a).run();
async function input(r){const raw=await r.text();requireThat(raw.length<80000,'Request is too large.',413);try{return JSON.parse(raw)}catch{throw new Problem(400,'Invalid request.')}}
const isAdmin=u=>u.roles.includes('coordinator');
async function membership(db,u,oid,manage=false){const m=await first(db,'SELECT * FROM cb_members WHERE organisation_id=? AND user_id=?',oid,u.id);requireThat(isAdmin(u)||m&&(manage?m.role==='owner'||m.role==='manager':true),'You do not have access to this organisation.',403);return m;}
async function records(db,userId){return all(db,`SELECT c.id,c.project_id,c.task_id,c.issued_at,c.correction_status,c.correction_reason,c.visibility,p.title AS project_title,p.impact_status,p.execution_status,t.title AS task_title,t.mode,t.brief FROM cb_credentials c JOIN cb_projects p ON p.id=c.project_id JOIN cb_tasks t ON t.id=c.task_id WHERE c.contributor_id=? ORDER BY c.issued_at DESC`,userId);}
async function recap(db,u,body){const from=date(body.from,'Start date'),to=date(body.to,'End date');requireThat(from<=to,'Choose an end date after the start date.');let entries,name=u.name,projects=[],funding=[];
 if(body.organisationId){await membership(db,u,body.organisationId);const org=await first(db,'SELECT name FROM cb_organisations WHERE id=?',body.organisationId);name=org.name;
 entries=await all(db,`SELECT c.id,c.project_id,c.task_id,c.issued_at,c.correction_status,p.title AS project_title,p.impact_status,p.execution_status,t.title AS task_title,t.mode FROM cb_affiliations a JOIN cb_credentials c ON c.id=a.credential_id JOIN cb_projects p ON p.id=c.project_id JOIN cb_tasks t ON t.id=c.task_id WHERE a.organisation_id=? AND a.consent=1 AND c.visibility='public' AND c.issued_at>=? AND c.issued_at<? AND c.correction_status!='revoked'`,body.organisationId,from,to+'T23:59:59.999Z');
 funding=await all(db,`SELECT f.id,f.project_id,f.type,f.amount_kobo,f.material_description,f.quantity,f.unit,f.status,f.delivery_record FROM cb_org_support s JOIN cb_funding f ON f.id=s.funding_id WHERE s.organisation_id=? AND f.created_at>=? AND f.created_at<?`,body.organisationId,from,to+'T23:59:59.999Z');
 }else entries=(await records(db,u.id)).filter(c=>c.issued_at>=from&&c.issued_at<to+'T23:59:59.999Z'&&c.correction_status!=='revoked');
 const ids=[...new Set([...entries.map(c=>c.project_id),...funding.map(f=>f.project_id)])];for(const pid of ids){const p=await first(db,'SELECT id,title,execution_status,impact_status FROM cb_projects WHERE id=?',pid);if(p)projects.push(p)}
 const confirmed=funding.filter(f=>f.type==='money'&&['held','released'].includes(f.status));const materials=funding.filter(f=>f.type==='material'&&f.delivery_record&&f.status==='released');
 return {name,from,to,entries,projects,moneyKobo:confirmed.reduce((s,f)=>s+f.amount_kobo,0),materials:materials.map(f=>({description:f.material_description,quantity:f.quantity,unit:f.unit})),volunteer:entries.filter(c=>c.mode==='volunteer').length,paid:entries.filter(c=>c.mode==='paid').length,generatedAt:stamp()};
}
async function publicShare(db,s){const stored=JSON.parse(s.data_json);const ids=stored.entries.map(c=>c.id);const entries=[];for(const id of ids){const c=await first(db,`SELECT c.id,c.project_id,c.issued_at,c.correction_status,c.correction_reason,p.title AS project_title,t.title AS task_title,t.mode FROM cb_credentials c JOIN cb_projects p ON p.id=c.project_id JOIN cb_tasks t ON t.id=c.task_id WHERE c.id=?`,id);if(!c)continue;if(s.organisation_id){const a=await first(db,'SELECT consent FROM cb_affiliations WHERE credential_id=? AND organisation_id=?',id,s.organisation_id);if(!a?.consent||!(await first(db,"SELECT 1 FROM cb_credentials WHERE id=? AND visibility='public'",id)))continue;}entries.push(c)}
 const current=entries.filter(c=>c.correction_status!=='revoked');return {...stored,entries,verified:current.length,volunteer:current.filter(c=>c.mode==='volunteer').length,paid:current.filter(c=>c.mode==='paid').length,shareId:s.id,type:s.type,visibility:s.visibility,verificationCheckedAt:stamp()};
}
export async function community(request,env,path,user){const db=env.CB_DB,method=request.method;let m;
 if(!user){m=path.match(/^\/public\/shares\/([^/]+)$/);if(method==='GET'&&m){const s=await first(db,"SELECT * FROM cb_shares WHERE id=? AND visibility IN ('link','public')",m[1]);requireThat(s,'This shared record is private or unavailable.',404);return reply({share:await publicShare(db,s)})}m=path.match(/^\/public\/credentials\/([^/]+)$/);const shareId=new URL(request.url).searchParams.get('share');if(method==='GET'&&m&&shareId){const s=await first(db,"SELECT * FROM cb_shares WHERE id=? AND visibility IN ('link','public')",shareId);requireThat(s,'Shared record unavailable.',404);const shared=await publicShare(db,s);const entry=shared.entries.find(e=>e.id===m[1]);requireThat(entry,'Credential not included in this share.',404);return reply({credential:{...entry,decision:'verified'}})}return;}
 if(method==='GET'&&path==='/accounts'){requireThat(isAdmin(user),'Administrator access required.',403);return reply({accounts:await all(db,'SELECT user_id,name,email FROM cb_accounts ORDER BY name')})}
 if(method==='GET'&&path==='/activity'){requireThat(isAdmin(user),'Administrator access required.',403);return reply({activity:await all(db,'SELECT * FROM cb_activity ORDER BY created_at DESC LIMIT 100')})}
 if(method==='GET'&&path==='/interests'){requireThat(isAdmin(user),'Administrator access required.',403);return reply({interests:await all(db,'SELECT i.*,a.name,p.title FROM cb_interests i JOIN cb_accounts a ON a.user_id=i.user_id JOIN cb_projects p ON p.id=i.project_id ORDER BY i.created_at DESC')})}
 m=path.match(/^\/projects\/([^/]+)\/interest$/);if(method==='POST'&&m){const b=await input(request);requireThat(await first(db,"SELECT 1 FROM cb_projects WHERE id=? AND published=1 AND execution_status IN ('structured','active')",m[1]),'This project is not accepting requests.');await run(db,'INSERT INTO cb_interests VALUES (?,?,?,?) ON CONFLICT(project_id,user_id) DO UPDATE SET note=excluded.note',m[1],user.id,text(b.note,'How you can help'),stamp());return reply({ok:true})}
 m=path.match(/^\/shares\/([^/]+)$/);if(method==='GET'&&m){const s=await first(db,'SELECT * FROM cb_shares WHERE id=? AND owner_id=?',m[1],user.id);requireThat(s,'Record unavailable.',404);return reply({share:await publicShare(db,s)})}
 if(method==='GET'&&path==='/proposals'){return reply({proposals:await all(db,'SELECT * FROM cb_proposals '+(isAdmin(user)?'':'WHERE proposer_id=? ')+'ORDER BY updated_at DESC',...(isAdmin(user)?[]:[user.id]))})}
 if(method==='POST'&&path==='/proposals'){const b=await input(request),id=uid();if(b.organisationId)await membership(db,user,b.organisationId);if(b.previousId){const prev=await first(db,'SELECT * FROM cb_proposals WHERE id=?',b.previousId);requireThat(prev&&prev.proposer_id===user.id&&prev.status==='rejected','Choose your own rejected proposal to revise.');}await run(db,'INSERT INTO cb_proposals (id,proposer_id,organisation_id,title,problem,audience,outcome,permissions,safety,resources,timing,participation,previous_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',id,user.id,b.organisationId||null,text(b.title,'Title',180),text(b.problem,'Problem'),text(b.audience,'Place and people'),text(b.outcome,'Public benefit'),text(b.permissions,'Permissions'),text(b.safety,'Safety and privacy'),String(b.resources||'').slice(0,6000),String(b.timing||'').slice(0,6000),String(b.participation||'Proposer').slice(0,500),b.previousId||null,stamp(),stamp());return reply({id},201)}
 m=path.match(/^\/proposals\/([^/]+)$/);if(m){const p=await first(db,'SELECT * FROM cb_proposals WHERE id=?',m[1]);requireThat(p,'Proposal not found.',404);requireThat(isAdmin(user)||p.proposer_id===user.id,'This proposal is private.',403);if(method==='POST'){const b=await input(request);if(isAdmin(user)&&b.status){requireThat(['submitted','reviewing','clarification','approved','rejected'].includes(b.status),'Choose a review decision.');requireThat(!['approved','rejected'].includes(p.status),'This decision is final. A rejected proposal can be revised as a new submission.');await run(db,'UPDATE cb_proposals SET status=?,feedback=?,updated_at=? WHERE id=?',b.status,text(b.feedback,'Decision reason'),stamp(),p.id);await run(db,'INSERT INTO cb_activity VALUES (?,?,?,?,?,?)',uid(),user.id,'proposal '+b.status,p.id,b.feedback,stamp());}else{requireThat(p.proposer_id===user.id&&p.status==='clarification','Clarification must be requested first.');await run(db,"UPDATE cb_proposals SET reply=?,status='submitted',updated_at=? WHERE id=?",text(b.reply,'Your clarification'),stamp(),p.id);}return reply({ok:true})}}
 if(method==='GET'&&path==='/organisations')return reply({organisations:await all(db,'SELECT o.*,m.role AS membership_role FROM cb_organisations o JOIN cb_members m ON m.organisation_id=o.id WHERE m.user_id=?',user.id)});
 if(method==='POST'&&path==='/organisations'){const b=await input(request),id=uid();await db.batch([db.prepare('INSERT INTO cb_organisations VALUES (?,?,?,?,?)').bind(id,text(b.name,'Organisation name',180),text(b.description,'What your organisation does'),user.id,stamp()),db.prepare("INSERT INTO cb_members VALUES (?,?,'owner',?)").bind(id,user.id,stamp())]);return reply({id},201)}
 m=path.match(/^\/organisations\/([^/]+)(?:\/(members|support))?$/);if(m){const oid=m[1];await membership(db,user,oid,method==='POST');if(method==='GET')return reply({organisation:await first(db,'SELECT * FROM cb_organisations WHERE id=?',oid),members:await all(db,'SELECT m.user_id,m.role,a.name FROM cb_members m JOIN cb_accounts a ON a.user_id=m.user_id WHERE m.organisation_id=?',oid),support:await all(db,'SELECT f.type,f.amount_kobo,f.material_description,f.quantity,f.unit,f.status,p.id AS project_id,p.title FROM cb_org_support s JOIN cb_funding f ON f.id=s.funding_id JOIN cb_projects p ON p.id=f.project_id WHERE s.organisation_id=?',oid)});
 if(method==='POST'&&m[2]==='members'){const b=await input(request);requireThat(['member','manager'].includes(b.role),'Choose member or manager.');const a=await first(db,'SELECT user_id FROM cb_accounts WHERE lower(email)=?',text(b.email,'Member email',254).toLowerCase());requireThat(a,'Ask this person to sign in to CivicBench first.',404);const org=await first(db,'SELECT owner_id FROM cb_organisations WHERE id=?',oid);requireThat(a.user_id!==org.owner_id,'The organisation owner’s role cannot be changed here.');await run(db,'INSERT INTO cb_members VALUES (?,?,?,?) ON CONFLICT(organisation_id,user_id) DO UPDATE SET role=excluded.role',oid,a.user_id,b.role,stamp());return reply({ok:true})}
 if(method==='POST'&&m[2]==='support'){requireThat(isAdmin(user),'An administrator confirms support records.',403);const b=await input(request);requireThat(await first(db,'SELECT id FROM cb_funding WHERE id=?',b.fundingId),'Funding record not found.',404);await run(db,'INSERT INTO cb_org_support VALUES (?,?)',oid,b.fundingId);return reply({ok:true})}}
 if(method==='GET'&&path==='/civic-cv')return reply({name:user.name,entries:await records(db,user.id),shares:await all(db,'SELECT id,type,visibility,created_at FROM cb_shares WHERE owner_id=? ORDER BY created_at DESC',user.id)});
 if(method==='POST'&&path==='/affiliations'){const b=await input(request);await membership(db,user,b.organisationId);requireThat(await first(db,'SELECT 1 FROM cb_credentials WHERE id=? AND contributor_id=?',b.credentialId,user.id),'Choose your own contribution.',403);await run(db,'INSERT INTO cb_affiliations VALUES (?,?,?) ON CONFLICT(credential_id,organisation_id) DO UPDATE SET consent=excluded.consent',b.credentialId,b.organisationId,b.consent===true?1:0);return reply({ok:true})}
 if(method==='POST'&&path==='/recap')return reply({recap:await recap(db,user,await input(request))});
 if(method==='POST'&&path==='/shares'){const b=await input(request);requireThat(['cv','recap','contribution'].includes(b.type),'Choose a sharing format.');requireThat(['private','link','public'].includes(b.visibility),'Choose who can see this.');requireThat(Array.isArray(b.entryIds)&&b.entryIds.length<=200,'Choose at most 200 contributions.');if(b.visibility!=='private')requireThat(b.consent===true,'Confirm sharing these records.');if(b.organisationId)await membership(db,user,b.organisationId,true);
 const source=b.type==='recap'?await recap(db,user,b):{name:user.name,entries:await records(db,user.id),generatedAt:stamp()};requireThat(b.entryIds.every(id=>source.entries.some(c=>c.id===id&&c.correction_status!=='revoked')),'Only your eligible verified contributions can be included.');source.entries=source.entries.filter(c=>b.entryIds.includes(c.id)&&c.correction_status!=='revoked');requireThat(b.type==='recap'||source.entries.length>0,'Choose a verified contribution.');if(b.type==='contribution')requireThat(source.entries.length===1,'Choose one contribution.');const id=uid();await run(db,'INSERT INTO cb_shares VALUES (?,?,?,?,?,?,?,?)',id,user.id,b.organisationId||null,b.type,b.visibility,JSON.stringify(source),stamp(),stamp());return reply({id},201)}
 m=path.match(/^\/shares\/([^/]+)$/);if(m&&method==='POST'){const b=await input(request);const s=await first(db,'SELECT * FROM cb_shares WHERE id=?',m[1]);requireThat(s&&s.owner_id===user.id,'Only the creator can change this share.',403);if(s.organisation_id)await membership(db,user,s.organisation_id,true);requireThat(['private','link','public'].includes(b.visibility),'Choose visibility.');if(b.visibility!=='private')requireThat(b.consent===true,'Confirm sharing.');await run(db,'UPDATE cb_shares SET visibility=?,updated_at=? WHERE id=?',b.visibility,stamp(),s.id);return reply({ok:true})}
}

