const host='https://civicbench-api.akintomiwaposi.workers.dev';
export async function identityFetch(env,url,options={},fallback=fetch){const init={...options,redirect:'manual'};const response=await (env.CB_IDENTITY?env.CB_IDENTITY.fetch(url,init):fallback(url,init));if(response.status>=300&&response.status<400)throw new Error('Identity service returned an unexpected redirect.');return response}
export function sessionToken(request){const auth=request.headers.get('Authorization')||'';const cookie=(request.headers.get('Cookie')||'').split(';').map(v=>v.trim()).find(v=>v.startsWith('__Host-cb_session='));if(cookie)return decodeURIComponent(cookie.slice('__Host-cb_session='.length));return /^Bearer (?!cookie$)[A-Za-z0-9_.-]+$/.test(auth)?auth.slice(7):'';}
export async function identityProxy(request,env,fetcher=fetch){const url=new URL(request.url),path=url.pathname;const fail=(error,status)=>Response.json({error},{status,headers:{'Cache-Control':'no-store'}});if(request.method==='POST'&&request.headers.get('Origin')&&request.headers.get('Origin')!==url.origin)return fail('Cross-origin request rejected.',403);
 if(path==='/api/account-status'&&request.method==='GET'){if(!env.CB_DB)return fail('Account access is being configured.',503);try{const r=await identityFetch(env,host+'/api/me',{},fetcher);const value=await r.json();if(!r.ok||!Object.hasOwn(value,'user'))return fail('Account service unavailable.',503);return Response.json({ready:true},{headers:{'Cache-Control':'no-store'}})}catch{return fail('Account service unavailable.',503)}}
 if(path==='/api/logout'&&request.method==='POST')return Response.json({ok:true},{headers:{'Set-Cookie':'__Host-cb_session=; Secure; HttpOnly; SameSite=Lax; Path=/; Max-Age=0','Cache-Control':'no-store'}});
 if(path==='/api/me'&&request.method==='GET'){const token=sessionToken(request);if(!token)return fail('Sign in to continue.',401);const r=await identityFetch(env,host+path,{headers:{Authorization:'Bearer '+token},redirect:'manual'},fetcher);return new Response(r.body,{status:r.status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}})}
 if(request.method!=='POST'||!['/api/login','/api/register'].includes(path))return fail('This endpoint has moved.',410);if(!env.CB_DB)return fail('Account access is being configured. Please try again shortly.',503);
 const ip=request.headers.get('CF-Connecting-IP')||'unknown',period=Math.floor(Date.now()/60000),key=ip+':'+path+':'+period;await env.CB_DB.prepare('INSERT INTO cb_rate_limits VALUES (?,1,?) ON CONFLICT(rate_key) DO UPDATE SET count=count+1').bind(key,period+5).run();const rate=await env.CB_DB.prepare('SELECT count FROM cb_rate_limits WHERE rate_key=?').bind(key).first();if(rate.count>10)return fail('Too many attempts. Please wait a minute.',429);await env.CB_DB.prepare('DELETE FROM cb_rate_limits WHERE expires_at<?').bind(period).run();
 let b;try{const raw=await request.text();if(raw.length>5000)return fail('Request too large.',413);b=JSON.parse(raw)}catch{return fail('Check your account details.',400)}const email=String(b.email||'').trim().toLowerCase(),password=String(b.password||'');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254||password.length>128||!password)return fail('Enter a valid email and password.',400);if(email.endsWith('@demo.com'))return fail('Demo accounts are unavailable.',403);const payload={email,password};if(path==='/api/register'){if(password.length<10)return fail('Use a password of at least 10 characters.',400);payload.name=String(b.name||'').trim().slice(0,180);if(!payload.name)return fail('Enter your name.',400);payload.role='citizen';}
 const r=await identityFetch(env,host+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),redirect:'manual'},fetcher);let value;try{value=await r.json()}catch{return fail('Account service unavailable. Please try again.',502)}if(!r.ok)return fail(String(value.error||'Check your account details.'),r.status);
 const headers={'Cache-Control':'no-store'};if(value.token){headers['Set-Cookie']='__Host-cb_session='+encodeURIComponent(value.token)+'; Secure; HttpOnly; SameSite=Lax; Path=/; Max-Age=86400';return Response.json({token:'cookie'},{headers})}return Response.json({ok:true},{headers});
}

