PRAGMA foreign_keys = ON;
-- Additive namespace: existing users/tasks/submissions/transactions are untouched.
CREATE TABLE IF NOT EXISTS cb_roles (
 user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('coordinator','steward','contributor','reviewer','funder')), PRIMARY KEY(user_id,role)
);
CREATE TABLE IF NOT EXISTS cb_projects (
 id TEXT PRIMARY KEY, title TEXT NOT NULL, problem TEXT NOT NULL, audience TEXT NOT NULL,
 outcome TEXT NOT NULL, proposer TEXT NOT NULL, steward TEXT NOT NULL, steward_id TEXT NOT NULL,
 scope TEXT NOT NULL, resources TEXT NOT NULL, permissions TEXT NOT NULL, safety TEXT NOT NULL,
 evidence TEXT NOT NULL, target_date TEXT NOT NULL, dissemination TEXT NOT NULL, closing_rule TEXT NOT NULL,
 previous_id TEXT REFERENCES cb_projects(id), proposal_id TEXT UNIQUE, execution_status TEXT NOT NULL DEFAULT 'proposed'
 CHECK(execution_status IN ('proposed','screening','rejected','structured','active','completed','closed')),
 impact_status TEXT NOT NULL DEFAULT 'not yet assessed'
 CHECK(impact_status IN ('not yet assessed','pending','partly resolved','resolved','unresolved')),
 completion_record TEXT NOT NULL DEFAULT '', impact_evidence TEXT NOT NULL DEFAULT '', outstanding_need TEXT NOT NULL DEFAULT '',
 next_impact_review_date TEXT, closed_at TEXT, published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0,1)),
 public_summary TEXT NOT NULL DEFAULT '', dissemination_record TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_decisions (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES cb_projects(id), actor_id TEXT NOT NULL,
 decision TEXT NOT NULL, reason TEXT NOT NULL, checks_json TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_funding (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES cb_projects(id), funder_id TEXT NOT NULL, funder_name TEXT NOT NULL,
 type TEXT NOT NULL CHECK(type IN ('money','material')), amount_kobo INTEGER NOT NULL DEFAULT 0 CHECK(typeof(amount_kobo)='integer' AND amount_kobo>=0),
 material_description TEXT NOT NULL DEFAULT '', quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), unit TEXT NOT NULL DEFAULT '',
 status TEXT NOT NULL CHECK(status IN ('pledged','committed','held','released','refunded')),
 agreement_ref TEXT NOT NULL, payment_route TEXT NOT NULL, delivery_record TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_tasks (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES cb_projects(id), title TEXT NOT NULL, brief TEXT NOT NULL,
 rubric TEXT NOT NULL, rubric_version INTEGER NOT NULL DEFAULT 1, evidence_standard TEXT NOT NULL,
 mode TEXT NOT NULL CHECK(mode IN ('paid','volunteer')), reward_kobo INTEGER NOT NULL DEFAULT 0 CHECK(typeof(reward_kobo)='integer' AND reward_kobo>=0),
 deadline TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','claimed','submitted','under review','accepted','rejected','disputed','closed')),
 capacity INTEGER NOT NULL DEFAULT 1 CHECK(capacity>=1 AND capacity<=20), reviews_required INTEGER NOT NULL DEFAULT 1 CHECK(reviews_required IN (1,2)),
 terms TEXT NOT NULL, steward_signoff TEXT NOT NULL, funder_signoff TEXT NOT NULL DEFAULT '', acceptance_by TEXT NOT NULL,
 created_at TEXT NOT NULL, CHECK((mode='volunteer' AND reward_kobo=0) OR (mode='paid' AND reward_kobo>0))
);
CREATE TABLE IF NOT EXISTS cb_allocations (
 task_id TEXT NOT NULL REFERENCES cb_tasks(id), funding_id TEXT NOT NULL REFERENCES cb_funding(id),
 amount_kobo INTEGER NOT NULL CHECK(typeof(amount_kobo)='integer' AND amount_kobo>0), PRIMARY KEY(task_id,funding_id)
);
CREATE TRIGGER IF NOT EXISTS cb_allocate_guard BEFORE INSERT ON cb_allocations BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM cb_tasks t JOIN cb_funding f ON f.project_id=t.project_id WHERE t.id=NEW.task_id AND f.id=NEW.funding_id AND f.type='money' AND f.status IN ('committed','held') AND t.status='draft') THEN RAISE(ABORT,'Funding must be committed to the same project; task must be draft') END;
 SELECT CASE WHEN (SELECT COALESCE(SUM(amount_kobo),0) FROM cb_allocations WHERE funding_id=NEW.funding_id)+NEW.amount_kobo > (SELECT amount_kobo FROM cb_funding WHERE id=NEW.funding_id) THEN RAISE(ABORT,'Funding is already allocated') END;
END;
CREATE TRIGGER IF NOT EXISTS cb_open_guard BEFORE UPDATE OF status ON cb_tasks WHEN NEW.status='open' BEGIN
 SELECT CASE WHEN (SELECT execution_status FROM cb_projects WHERE id=NEW.project_id) NOT IN ('structured','active') THEN RAISE(ABORT,'Project must pass screening') END;
 SELECT CASE WHEN NEW.mode='paid' AND ((SELECT COALESCE(SUM(amount_kobo),0) FROM cb_allocations WHERE task_id=NEW.id)<NEW.reward_kobo*NEW.capacity OR NEW.funder_signoff='') THEN RAISE(ABORT,'Paid assignments need full committed funding and funder sign-off') END;
END;
CREATE TABLE IF NOT EXISTS cb_assignments (
 task_id TEXT NOT NULL REFERENCES cb_tasks(id), contributor_id TEXT NOT NULL, assigned_at TEXT NOT NULL,
 agreed_at TEXT, agreed_terms TEXT, PRIMARY KEY(task_id,contributor_id)
);
CREATE TRIGGER IF NOT EXISTS cb_assignment_guard BEFORE INSERT ON cb_assignments BEGIN
 SELECT CASE WHEN (SELECT status FROM cb_tasks WHERE id=NEW.task_id) NOT IN ('open','claimed') THEN RAISE(ABORT,'Task is not open for assignment') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM cb_assignments WHERE task_id=NEW.task_id)>=(SELECT capacity FROM cb_tasks WHERE id=NEW.task_id) THEN RAISE(ABORT,'Task capacity is full') END;
END;
CREATE TRIGGER IF NOT EXISTS cb_terms_frozen BEFORE UPDATE OF rubric,terms,mode,reward_kobo,capacity ON cb_tasks WHEN EXISTS(SELECT 1 FROM cb_assignments WHERE task_id=OLD.id) BEGIN
 SELECT RAISE(ABORT,'Assigned terms are frozen; create an amended task with fresh agreement');
END;
CREATE TABLE IF NOT EXISTS cb_contributions (
 id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES cb_tasks(id), contributor_id TEXT NOT NULL,
 submission TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','under review','rejected','acceptance','accepted','disputed')),
 submitted_at TEXT NOT NULL, acceptance_due TEXT, accepted_at TEXT, UNIQUE(task_id,contributor_id)
);
CREATE TABLE IF NOT EXISTS cb_evidence (
 id TEXT PRIMARY KEY, contribution_id TEXT NOT NULL REFERENCES cb_contributions(id), object_key TEXT NOT NULL UNIQUE,
 filename TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>0), created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_rework_history (
 id TEXT PRIMARY KEY, contribution_id TEXT NOT NULL REFERENCES cb_contributions(id),
 previous_submission TEXT NOT NULL, previous_reviews_json TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_review_assignments (
 contribution_id TEXT NOT NULL REFERENCES cb_contributions(id), reviewer_id TEXT NOT NULL, assigned_at TEXT NOT NULL, PRIMARY KEY(contribution_id,reviewer_id)
);
CREATE TABLE IF NOT EXISTS cb_reviews (
 id TEXT PRIMARY KEY, contribution_id TEXT NOT NULL REFERENCES cb_contributions(id), reviewer_id TEXT NOT NULL,
 decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), accuracy INTEGER NOT NULL CHECK(accuracy BETWEEN 0 AND 100),
 public_value INTEGER NOT NULL CHECK(public_value BETWEEN 0 AND 100), comments TEXT NOT NULL, conflict_declared INTEGER NOT NULL CHECK(conflict_declared=1),
 fee_kobo INTEGER NOT NULL CHECK(typeof(fee_kobo)='integer' AND fee_kobo>=0), minutes INTEGER NOT NULL CHECK(minutes>=0), created_at TEXT NOT NULL, UNIQUE(contribution_id,reviewer_id)
);
CREATE TRIGGER IF NOT EXISTS cb_review_guard BEFORE INSERT ON cb_reviews BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM cb_review_assignments WHERE contribution_id=NEW.contribution_id AND reviewer_id=NEW.reviewer_id) THEN RAISE(ABORT,'Reviewer must be assigned') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM cb_contributions c JOIN cb_tasks t ON t.id=c.task_id WHERE c.id=NEW.contribution_id AND (c.contributor_id=NEW.reviewer_id OR EXISTS(SELECT 1 FROM cb_funding f WHERE f.project_id=t.project_id AND f.funder_id=NEW.reviewer_id))) THEN RAISE(ABORT,'Reviewer conflict of interest') END;
END;
CREATE TABLE IF NOT EXISTS cb_disputes (
 id TEXT PRIMARY KEY, contribution_id TEXT NOT NULL REFERENCES cb_contributions(id), raised_by TEXT NOT NULL,
 reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), panel_json TEXT, decision TEXT, created_at TEXT NOT NULL, resolved_at TEXT
);
CREATE TABLE IF NOT EXISTS cb_credentials (
 id TEXT PRIMARY KEY, contribution_id TEXT NOT NULL UNIQUE REFERENCES cb_contributions(id), contributor_id TEXT NOT NULL,
 project_id TEXT NOT NULL REFERENCES cb_projects(id), task_id TEXT NOT NULL REFERENCES cb_tasks(id), verifier_id TEXT NOT NULL,
 decision TEXT NOT NULL DEFAULT 'verified', issued_at TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','public')),
 correction_status TEXT NOT NULL DEFAULT 'current' CHECK(correction_status IN ('current','corrected','revoked')), correction_reason TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS cb_payments (
 id TEXT PRIMARY KEY, contribution_id TEXT NOT NULL UNIQUE REFERENCES cb_contributions(id), amount_kobo INTEGER NOT NULL CHECK(typeof(amount_kobo)='integer' AND amount_kobo>0),
 route TEXT NOT NULL, reference TEXT NOT NULL, paid_at TEXT NOT NULL, recorded_by TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_costs (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES cb_projects(id), category TEXT NOT NULL,
 minutes INTEGER NOT NULL CHECK(minutes>=0), rate_kobo INTEGER NOT NULL CHECK(typeof(rate_kobo)='integer' AND rate_kobo>=0),
 direct_kobo INTEGER NOT NULL CHECK(typeof(direct_kobo)='integer' AND direct_kobo>=0), donated INTEGER NOT NULL CHECK(donated IN (0,1)), note TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_corrections (
 id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES cb_projects(id), summary TEXT NOT NULL, corrected_at TEXT NOT NULL, actor_id TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_gate_decisions (
 gate INTEGER PRIMARY KEY CHECK(gate IN (1,2,3)), decision TEXT NOT NULL CHECK(decision IN ('proceed','retest','redesign')),
 evidence TEXT NOT NULL, actor_id TEXT NOT NULL, recorded_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS cb_project_public ON cb_projects(published);
CREATE INDEX IF NOT EXISTS cb_task_project ON cb_tasks(project_id);
CREATE INDEX IF NOT EXISTS cb_contribution_task ON cb_contributions(task_id);
CREATE TABLE IF NOT EXISTS cb_accounts (user_id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cb_proposals (
 id TEXT PRIMARY KEY,proposer_id TEXT NOT NULL,organisation_id TEXT,title TEXT NOT NULL,problem TEXT NOT NULL,
 audience TEXT NOT NULL,outcome TEXT NOT NULL,permissions TEXT NOT NULL,safety TEXT NOT NULL,resources TEXT NOT NULL,
 timing TEXT NOT NULL,participation TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','reviewing','clarification','approved','rejected')),
 feedback TEXT NOT NULL DEFAULT '',reply TEXT NOT NULL DEFAULT '',previous_id TEXT REFERENCES cb_proposals(id),
 project_id TEXT REFERENCES cb_projects(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS cb_organisations (id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,owner_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cb_members (organisation_id TEXT NOT NULL REFERENCES cb_organisations(id),user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','manager','member')),joined_at TEXT NOT NULL,PRIMARY KEY(organisation_id,user_id));
CREATE TABLE IF NOT EXISTS cb_org_support (organisation_id TEXT NOT NULL REFERENCES cb_organisations(id),funding_id TEXT NOT NULL UNIQUE REFERENCES cb_funding(id),PRIMARY KEY(organisation_id,funding_id));
CREATE TABLE IF NOT EXISTS cb_affiliations (credential_id TEXT NOT NULL REFERENCES cb_credentials(id),organisation_id TEXT NOT NULL REFERENCES cb_organisations(id),consent INTEGER NOT NULL CHECK(consent IN (0,1)),PRIMARY KEY(credential_id,organisation_id));
CREATE TABLE IF NOT EXISTS cb_shares (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,organisation_id TEXT REFERENCES cb_organisations(id),type TEXT NOT NULL CHECK(type IN ('cv','recap','contribution')),visibility TEXT NOT NULL CHECK(visibility IN ('private','link','public')),data_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cb_activity (id TEXT PRIMARY KEY,actor_id TEXT NOT NULL,action TEXT NOT NULL,record_id TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cb_rate_limits (rate_key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cb_evidence_payloads (object_key TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cb_interests (project_id TEXT NOT NULL REFERENCES cb_projects(id),user_id TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(project_id,user_id));

