import {handle} from '../../core/service.mjs';
import {identityProxy} from '../../core/identity.mjs';
import {statements} from '../../core/schema.mjs';
let schemaReady;
async function initialise(db){if(!db)return;if(!schemaReady)schemaReady=(async()=>{try{await db.prepare('SELECT 1 FROM cb_interests LIMIT 1').first()}catch{await db.batch(statements.map(sql=>db.prepare(sql)))}})().catch(e=>{schemaReady=null;throw e});await schemaReady;}
export async function onRequest(context){try{await initialise(context.env.CB_DB);let actor;const env={...context.env,setAuditActor:id=>actor=id};const path=new URL(context.request.url).pathname;const r=path.startsWith('/api/v2/')?await handle(context.request,env):await identityProxy(context.request,env);if(actor&&context.request.method==='POST'&&r.ok){let id='';try{id=(await r.clone().json()).id||path.split('/')[4]||''}catch{}await env.CB_DB.prepare('INSERT INTO cb_activity VALUES (?,?,?,?,?,?)').bind(crypto.randomUUID(),actor,path.replace('/api/v2/',''),id,'Action completed',new Date().toISOString()).run().catch(()=>{});}return r}catch(error){console.error("CivicBench request failed",error.name,error.message);return Response.json({error:'The service is temporarily unavailable. Please try again.'},{status:503,headers:{'Cache-Control':'no-store'}})}}

