const statements=sql.split(/;\s*(?=CREATE)/).map(s=>s.trim().replace(/;$/,'')).filter(Boolean);
await writeFile('core/schema.mjs','export const statements='+JSON.stringify(statements)+';\n');
await rm('dist',{recursive:true,force:true});
