import {DatabaseSync} from 'node:sqlite';
export function d1(database) {
 const wrap=(sql,args=[])=>({bind(...values){return wrap(sql,values);},async all(){return {results:database.prepare(sql).all(...args)};},async first(){return database.prepare(sql).get(...args)||null;},async run(){const result=database.prepare(sql).run(...args);return {meta:{changes:Number(result.changes)}};},sql,args});
 return {prepare:wrap,async batch(statements){database.exec('BEGIN IMMEDIATE');try{const results=[];for(const s of statements)results.push(await s.run());database.exec('COMMIT');return results;}catch(e){database.exec('ROLLBACK');throw e;}}};
}
export {DatabaseSync};

