import test from 'node:test';import assert from 'node:assert/strict';
import {validateNeed,NEED_FIELDS,kobo,date,independent,canFinalize,WINDOW_MS,canMove,safePublicProject} from '../core/model.mjs';
test('canonical need record has twelve complete fields',()=>{assert.equal(NEED_FIELDS.length,12);const need=Object.fromEntries(NEED_FIELDS.map(([key])=>[key,key==='targetDate'?'2026-11-08':'Explicit detail']));assert.throws(()=>validateNeed({...need,title:'Pilot',stewardId:'1'}),/Closing rule/);assert.equal(validateNeed({...need,title:'Pilot',stewardId:'1',closingRule:'Replan or close unresolved.'}).title,'Pilot');delete need.permissions;assert.throws(()=>validateNeed({...need,title:'Pilot',stewardId:'1',closingRule:'Close'}),/Permissions/);});
test('money stays integer kobo without floating point multiplication drift',()=>{assert.equal(kobo('100.01'),10001);assert.equal(kobo('0.29'),29);assert.throws(()=>kobo('1.999'));assert.throws(()=>kobo('-1'));assert.throws(()=>kobo('9007199254740999'));});
test('invalid dates fail with a useful validation error',()=>{assert.throws(()=>date('2026-02-30','Target'),/valid date/);assert.throws(()=>date('2026-99-99','Target'),/valid date/);});
test('reviewers cannot review their own or funded work',()=>{assert.throws(()=>independent('2',{contributor_id:'2'},[]));assert.throws(()=>independent('3',{contributor_id:'2'},['3']));assert.doesNotThrow(()=>independent('4',{contributor_id:'2'},['3']));});
test('72-hour window and independent review gate all acceptance',()=>{const start=Date.now(),c={status:'acceptance',reviews_required:2,acceptance_due:new Date(start+WINDOW_MS).toISOString()};assert.throws(()=>canFinalize(c,2,0,start+WINDOW_MS-1),/window/);assert.throws(()=>canFinalize(c,1,0,start+WINDOW_MS),/Independent/);assert.throws(()=>canFinalize(c,2,1,start+WINDOW_MS),/dispute/);assert.doesNotThrow(()=>canFinalize(c,2,0,start+WINDOW_MS));});
test('rejected needs are terminal and completion does not imply resolved impact',()=>{assert.equal(canMove('rejected','structured'),false);assert.equal(canMove('active','completed'),true);const p=safePublicProject({execution_status:'completed',impact_status:'unresolved',proposer:'Private name',safety:'Private details'});assert.equal(p.impact_status,'unresolved');assert.equal('proposer' in p,false);assert.equal('safety' in p,false);});

