import test from 'node:test';import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';
import {DatabaseSync,d1} from '../scripts/sqlite.mjs';import {handle} from '../core/service.mjs';
import {NEED_FIELDS,WINDOW_MS} from '../core/model.mjs';
async function fixture(){const sqlite=new DatabaseSync(':memory:');sqlite.exec(await readFile(new URL('../migrations/0001_need_first.sql',import.meta.url),'utf8'));const db=d1(sqlite);const storage=new Map();const env={CB_DB:db,CB_COORDINATOR_IDS:'1',CB_EVIDENCE:{async put(k,v){storage.set(k,v);},async get(k){return storage.has(k)?{body:storage.get(k)}:null;},async delete(k){storage.delete(k);}}};for(const [uid,role] of [['2','contributor'],['3','reviewer'],['4','funder'],['5','reviewer'],['6','reviewer']])await db.prepare('INSERT INTO cb_roles VALUES (?,?)').bind(uid,role).run();const fetcher=async(_url,init)=>{const uid=init.headers.Authorization.split(' ')[1];return Response.json({user:{id:uid,name:'Test participant',email:'test@local.invalid'}});};
 const call=async(path,data,user='1',extra={})=>{const request=new Request('https://civicbench.test/api/v2'+path,{method:data?'POST':'GET',headers:{Authorization:'Bearer '+user,...(data?{'Content-Type':'application/json'}:{}),...extra.headers},...(data?{body:JSON.stringify(data)}:{}),...extra});const response=await handle(request,env,fetcher);const result=response.headers.get('content-type')?.includes('json')?await response.json():await response.text();return {status:response.status,result};};return {sqlite,db,env,call,storage};}
const need={...Object.fromEntries(NEED_FIELDS.map(([key])=>[key,key==='targetDate'?'2026-11-08':'Explicit pilot detail'])),title:'Pilot A need',stewardId:'1',closingRule:'Re-plan or close unresolved at target date.'};
async function project(f){const created=await f.call('/projects',need);assert.equal(created.status,201,JSON.stringify(created.result));const pid=created.result.id;const checks={publicBenefit:true,lawfulAuthority:true,privacyConsent:true,contributorSafety:true,clearDeliverable:true,independentReview:true};assert.equal((await f.call(`/projects/${pid}/screen`,{decision:'structured',reason:'All eligibility checks passed.',checks})).status,200);return pid;}
async function task(f,pid,mode='volunteer',capacity=1,reviewsRequired=1){const t=await f.call(`/projects/${pid}/tasks`,{title:'Explain the budget',brief:'Prepare a factual explainer',rubric:'Accuracy against source, then public usefulness',evidenceStandard:'PDF with source and method',mode,rewardKobo:mode==='paid'?10001:0,deadline:'2026-11-08',capacity,reviewsRequired,terms:mode==='paid'?'Paid reward as agreed':'Volunteer; no payment implied',stewardSignoff:'Written steward approval',funderSignoff:mode==='paid'?'Written funder approval':'',acceptanceBy:'4'});assert.equal(t.status,201,JSON.stringify(t.result));return t.result.id;}
async function contribute(f,tid){assert.equal((await f.call(`/tasks/${tid}/assign`,{contributorId:'2'})).status,200);assert.equal((await f.call(`/tasks/${tid}/submit`,{submission:'Evidence'},'2')).status,422);assert.equal((await f.call(`/tasks/${tid}/agree`,{agree:true},'2')).status,200);const submitted=await f.call(`/tasks/${tid}/submit`,{submission:'Verified explanation with source citations'},'2');assert.equal(submitted.status,201);const cid=submitted.result.id;const request=new Request('https://civicbench.test/api/v2/contributions/'+cid+'/evidence',{method:'POST',headers:{Authorization:'Bearer 2','Content-Type':'text/plain','X-File-Size':'14','X-Filename':'reference.txt'},body:'Source content'});const response=await handle(request,f.env,async()=>Response.json({user:{id:2,name:'Contributor',email:'test@local.invalid'}}));assert.equal(response.status,201);assert.equal((await f.call(`/contributions/${cid}/assign-reviewer`,{reviewerId:'3'})).status,200);return cid;}
const review={decision:'approved',accuracy:95,publicValue:90,comments:'Passed all rubric criteria',noConflict:true,accuracyPassed:true,feeKobo:0,minutes:30};
test('unfunded end-to-end workflow: terms, stored evidence, independent review, window, credential, honest impact',async()=>{const f=await fixture(),pid=await project(f),tid=await task(f,pid);assert.equal((await f.call(`/tasks/${tid}/open`,{})).status,200);const cid=await contribute(f,tid);assert.equal((await f.call(`/contributions/${cid}/review`,review,'3')).status,200);assert.equal((await f.call(`/contributions/${cid}/finalize`,{})).status,422);await f.db.prepare('UPDATE cb_contributions SET acceptance_due=? WHERE id=?').bind(new Date(Date.now()-1).toISOString(),cid).run();const final=await f.call(`/contributions/${cid}/finalize`,{});assert.equal(final.status,200,JSON.stringify(final.result));assert.equal((await f.call(`/contributions/${cid}/finalize`,{})).status,422);assert.equal((await f.call(`/projects/${pid}/outcome`,{executionStatus:'active',impactStatus:'pending',impactEvidence:'Delivery occurred; repair evidence not yet available.',outstandingNeed:'Repairs remain.',nextReview:'2026-12-01'})).status,200);assert.equal((await f.call(`/projects/${pid}/outcome`,{executionStatus:'completed',completionRecord:'Explainer delivered.',impactStatus:'unresolved',impactEvidence:'Authority has not yet acted.',outstandingNeed:'Repair pending',nextReview:'2026-12-01',disseminationRecord:'Sent to intended beneficiaries.'})).status,200);assert.equal((await f.call(`/projects/${pid}/publish`,{publicSummary:'A reviewed explainer was delivered.',privacyChecked:true})).status,200);const publicRecord=await f.call('/public/projects/'+pid);assert.equal(publicRecord.result.project.execution_status,'completed');assert.equal(publicRecord.result.project.impact_status,'unresolved');assert.equal('safety' in publicRecord.result.project,false);const credential=final.result.credentialId;assert.equal((await f.call('/public/credentials/'+credential)).status,404);assert.equal((await f.call('/credentials/'+credential,{visibility:'public'},'2')).status,200);assert.equal((await f.call('/public/credentials/'+credential)).status,200);assert.equal((await f.call(`/contributions/${cid}/payment`,{route:'Manual',reference:'X',paidAt:'2026-10-10',alreadyPaid:true})).status,422);f.sqlite.close();});
test('funded tasks require committed allocations; money cannot be allocated twice or paid before acceptance',async()=>{const f=await fixture(),pid=await project(f),tid=await task(f,pid,'paid');assert.equal((await f.call(`/tasks/${tid}/open`,{})).status,409);assert.equal((await f.call(`/projects/${pid}/funding`,{type:'money',amountKobo:10001,status:'committed',funderId:'4',funderName:'An organisation',agreementRef:'Signed written manual agreement',paymentRoute:'Manual agreement'})).status,201);const funding=(await f.call('/projects/'+pid)).result.funding[0];assert.equal((await f.call(`/tasks/${tid}/allocate`,{fundingId:funding.id,amountKobo:10001})).status,200);const tid2=await task(f,pid,'paid');assert.equal((await f.call(`/tasks/${tid2}/allocate`,{fundingId:funding.id,amountKobo:1})).status,409);assert.equal((await f.call(`/tasks/${tid}/open`,{})).status,200);const cid=await contribute(f,tid);assert.equal((await f.call(`/contributions/${cid}/payment`,{route:'Manual',reference:'X',paidAt:'2026-10-10',alreadyPaid:true})).status,422);assert.equal((await f.call(`/contributions/${cid}/review`,review,'3')).status,200);await f.db.prepare('UPDATE cb_contributions SET acceptance_due=? WHERE id=?').bind(new Date(Date.now()-1).toISOString(),cid).run();assert.equal((await f.call(`/contributions/${cid}/finalize`,{})).status,200);assert.equal((await f.call(`/contributions/${cid}/payment`,{route:'Written manual agreement',reference:'Bank receipt 123',paidAt:'2026-10-10',alreadyPaid:true})).status,200);assert.equal((await f.call(`/contributions/${cid}/payment`,{route:'Written manual agreement',reference:'Bank receipt 123',paidAt:'2026-10-10',alreadyPaid:true})).status,409);f.sqlite.close();});
test('supervised capacity, terminal rejection, resubmission links, role and privacy protections',async()=>{const f=await fixture();assert.equal((await f.call('/projects',need,'2')).status,403);const pid=await project(f),tid=await task(f,pid);await f.call(`/tasks/${tid}/open`,{});await f.call(`/tasks/${tid}/assign`,{contributorId:'2'});await f.db.prepare('INSERT INTO cb_roles VALUES (?,?)').bind('7','contributor').run();assert.equal((await f.call(`/tasks/${tid}/assign`,{contributorId:'7'})).status,409);assert.equal((await f.call('/projects/'+pid,null,'7')).status,403);const created=await f.call('/projects',need);const rejected=created.result.id;await f.call(`/projects/${rejected}/screen`,{decision:'rejected',reason:'Fails public benefit',checks:{}});assert.equal((await f.call(`/projects/${rejected}/screen`,{decision:'clarification',reason:'Try again'})).status,422);const revised=await f.call('/projects',{...need,previousId:rejected});assert.equal(revised.status,201);assert.equal((await f.call('/projects/'+revised.result.id)).result.project.previous_id,rejected);assert.equal((await f.call('/projects/'+rejected)).result.project.execution_status,'rejected');f.sqlite.close();});
test('two reviewers disagree: independent three-person panel and a fresh 72-hour window',async()=>{const f=await fixture(),pid=await project(f),tid=await task(f,pid,'volunteer',1,2);await f.call(`/tasks/${tid}/open`,{});const cid=await contribute(f,tid);await f.call(`/contributions/${cid}/assign-reviewer`,{reviewerId:'5'});assert.equal((await f.call(`/contributions/${cid}/review`,review,'3')).status,200);assert.equal((await f.call('/projects/'+pid)).result.contributions[0].status,'under review');assert.equal((await f.call(`/contributions/${cid}/review`,{...review,decision:'rejected'},'5')).status,200);assert.equal((await f.call('/projects/'+pid)).result.contributions[0].status,'disputed');assert.equal((await f.call(`/contributions/${cid}/resolve`,{panelIds:['3','5','2'],decision:'approved',accuracyPassed:true,reason:'Independent panel analysis'})).status,422);assert.equal((await f.call(`/contributions/${cid}/resolve`,{panelIds:['3','5','6'],decision:'approved',accuracyPassed:true,reason:'Independent panel analysis'})).status,200);assert.equal((await f.call(`/contributions/${cid}/finalize`,{})).status,422);await f.db.prepare('UPDATE cb_contributions SET acceptance_due=? WHERE id=?').bind(new Date(Date.now()-1).toISOString(),cid).run();assert.equal((await f.call(`/contributions/${cid}/finalize`,{})).status,200);f.sqlite.close();});
test('unconfigured production fails closed; cross-origin writes are rejected',async()=>{const r=await handle(new Request('https://civicbench.test/api/v2/public/projects'),{});assert.equal(r.status,200);assert.deepEqual((await r.json()).projects,[]);const w=await handle(new Request('https://civicbench.test/api/v2/projects',{method:'POST',headers:{Origin:'https://elsewhere.invalid'},body:'{}'}),{});assert.equal(w.status,403);});

