import test from 'node:test';import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';import {DatabaseSync,d1} from '../scripts/sqlite.mjs';import {handle} from '../core/service.mjs';import {statements} from '../core/schema.mjs';
async function fixture(){const sqlite=new DatabaseSync(':memory:');sqlite.exec(await readFile(new URL('../migrations/0001_need_first.sql',import.meta.url),'utf8'));const db=d1(sqlite),env={CB_DB:db,CB_COORDINATOR_IDS:'1'};const call=async(path,data,user='2')=>{const r=await handle(new Request('https://civicbench.test/api/v2'+path,{method:data?'POST':'GET',headers:{Authorization:'Bearer '+user,...(data?{'Content-Type':'application/json'}:{})},...(data?{body:JSON.stringify(data)}:{})}),env,async()=>Response.json({user:{id:user,name:'Person '+user,email:'person'+user+'@test.invalid'}}));return {status:r.status,result:await r.json()}};return {sqlite,db,call};}
test('public proposals stay private, clarification is trackable and rejection becomes a linked resubmission',async()=>{const f=await fixture();const b={title:'Library access',problem:'Unclear borrowing rules',audience:'Local readers',outcome:'Clear borrowing guide',permissions:'Library manager',safety:'No known concerns',participation:'Proposer'};const p=await f.call('/proposals',b);assert.equal(p.status,201);assert.equal((await f.call('/proposals',null,'3')).result.proposals.length,0);assert.equal((await f.call('/proposals',null,'1')).result.proposals.length,1);assert.equal((await f.call('/proposals/'+p.result.id,{status:'approved',feedback:'Looks suitable'},'3')).status,403);assert.equal((await f.call('/proposals/'+p.result.id,{status:'clarification',feedback:'Confirm permission'},'1')).status,200);assert.equal((await f.call('/proposals/'+p.result.id,{reply:'Permission confirmed'})).status,200);assert.equal((await f.call('/proposals/'+p.result.id,{status:'rejected',feedback:'Outside remit'},'1')).status,200);assert.equal((await f.call('/proposals/'+p.result.id,{status:'approved',feedback:'Changed mind'},'1')).status,422);assert.equal((await f.call('/proposals',{...b,previousId:p.result.id})).status,201);assert.equal((await f.call('/proposals',{...b,previousId:p.result.id},'3')).status,422);f.sqlite.close()});
test('organisation membership cannot be assigned by outsiders; sharing visibility and revoked counts stay correct',async()=>{const f=await fixture();await f.call('/me',null,'3');const org=(await f.call('/organisations',{name:'Local Action',description:'Community support'})).result.id;assert.equal((await f.call('/organisations/'+org+'/members',{email:'person3@test.invalid',role:'manager'},'4')).status,403);assert.equal((await f.call('/organisations/'+org+'/members',{email:'person3@test.invalid',role:'manager'})).status,200);const n='2026-10-10T00:00:00.000Z';f.sqlite.exec(`INSERT INTO cb_projects (id,title,problem,audience,outcome,proposer,steward,steward_id,scope,resources,permissions,safety,evidence,target_date,dissemination,closing_rule,created_at,updated_at) VALUES ('p','Library','Problem','Readers','Guide','Person','Steward','1','Scope','None','Permission','Safe','Proof','2026-11-01','Share','Close','${n}','${n}');INSERT INTO cb_tasks (id,project_id,title,brief,rubric,evidence_standard,mode,deadline,terms,steward_signoff,acceptance_by,created_at) VALUES ('t','p','Borrowing guide','Guide','Accuracy','Text','volunteer','2026-11-01','Volunteer','Agreed','1','${n}');INSERT INTO cb_contributions (id,task_id,contributor_id,submission,status,submitted_at) VALUES ('c','t','2','Guide','accepted','${n}');INSERT INTO cb_credentials (id,contribution_id,contributor_id,project_id,task_id,verifier_id,issued_at) VALUES ('v','c','2','p','t','3','${n}');`);
assert.equal((await f.call('/shares',{type:'cv',visibility:'link',entryIds:['v'],consent:false})).status,422);const s=(await f.call('/shares',{type:'cv',visibility:'link',entryIds:['v'],consent:true})).result.id;assert.equal((await f.call('/public/shares/'+s,null,'4')).result.share.verified,1);assert.equal((await f.call('/public/credentials/v?share='+s,null,'4')).status,200);assert.equal((await f.call('/shares',{type:'cv',visibility:'link',entryIds:['v'],consent:true},'3')).status,422);assert.equal((await f.call('/shares/'+s,{visibility:'private'},'3')).status,403);await f.call('/shares/'+s,{visibility:'private'});assert.equal((await f.call('/public/shares/'+s,null,'4')).status,404);assert.equal((await f.call('/shares/'+s)).status,200);await f.call('/shares/'+s,{visibility:'link',consent:true});await f.db.prepare("UPDATE cb_credentials SET correction_status='revoked',correction_reason='Source error' WHERE id='v'").run();const share=(await f.call('/public/shares/'+s,null,'4')).result.share;assert.equal(share.verified,0);assert.equal(share.entries[0].correction_status,'revoked');const recap=(await f.call('/recap',{from:'2026-01-01',to:'2026-12-31'})).result.recap;assert.equal(recap.entries.length,0);f.sqlite.close()});
test('compiled Cloudflare schema creates all tables and triggers as individual statements',async()=>{const sqlite=new DatabaseSync(':memory:');await d1(sqlite).batch(statements.map(s=>d1(sqlite).prepare(s)));assert.equal(sqlite.prepare('PRAGMA integrity_check').get().integrity_check,'ok');assert.equal(sqlite.prepare('SELECT COUNT(*) AS n FROM cb_evidence_payloads').get().n,0);sqlite.close()});

