import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {DatabaseSync,d1} from '../scripts/sqlite.mjs';
import {identityProxy,sessionToken,identityFetch} from '../core/identity.mjs';
import {handle} from '../core/service.mjs';
async function fixture(){const sqlite=new DatabaseSync(':memory:');sqlite.exec(await readFile(new URL('../migrations/0001_need_first.sql',import.meta.url),'utf8'));return {sqlite,db:d1(sqlite)}}
const unavailable=()=>{throw new Error('Public Worker fetch must not be used when the binding exists')};
test('registration uses the bound identity service, restricts roles and keeps the token in an HttpOnly cookie',async()=>{const f=await fixture();let received;const env={CB_DB:f.db,CB_IDENTITY:{fetch:async(url,options)=>{received={url,body:JSON.parse(options.body)};return Response.json({token:'test.session.token'})}}};const request=new Request('https://civicbench.test/api/register',{method:'POST',headers:{Origin:'https://civicbench.test','Content-Type':'application/json'},body:JSON.stringify({name:'Local Test',email:'local@test.invalid',password:'Test-only-credential-123',role:'coordinator'})});const r=await identityProxy(request,env,unavailable);assert.equal(r.status,200);assert.equal(received.body.role,'citizen');assert.equal(received.url.endsWith('/api/register'),true);assert.deepEqual(await r.json(),{token:'cookie'});assert.match(r.headers.get('Set-Cookie'),/Secure; HttpOnly; SameSite=Lax/);f.sqlite.close()});
test('account readiness checks the bound service and fails closed on connection failure',async()=>{const f=await fixture();const req=()=>new Request('https://civicbench.test/api/account-status');let r=await identityProxy(req(),{CB_DB:f.db,CB_IDENTITY:{fetch:async()=>Response.json({user:null})}},unavailable);assert.deepEqual(await r.json(),{ready:true});r=await identityProxy(req(),{CB_DB:f.db,CB_IDENTITY:{fetch:unavailable}},unavailable);assert.equal(r.status,503);f.sqlite.close()});
test('protected platform requests validate the cookie session through the identity binding',async()=>{const f=await fixture();let auth;const request=new Request('https://civicbench.test/api/v2/me',{headers:{Cookie:'__Host-cb_session=test.session.token'}});assert.equal(sessionToken(request),'test.session.token');const r=await handle(request,{CB_DB:f.db,CB_IDENTITY:{fetch:async(url,options)=>{auth=options.headers.Authorization;return Response.json({user:{id:'identity-test',name:'Local Test',email:'local@test.invalid'}})}}},unavailable);assert.equal(r.status,200);assert.equal(auth,'Bearer test.session.token');assert.equal(f.sqlite.prepare('SELECT user_id FROM cb_accounts').get().user_id,'identity-test');f.sqlite.close()});

test('identity requests use the supported manual mode and reject redirects without forwarding credentials',async()=>{let calls=0;const env={CB_IDENTITY:{fetch:async(url,options)=>{calls++;assert.equal(options.redirect,'manual');return new Response(null,{status:302,headers:{Location:'https://other.invalid'}})}}};await assert.rejects(identityFetch(env,'https://identity.invalid',{redirect:'error',headers:{Authorization:'Bearer test-only'}}),/unexpected redirect/);assert.equal(calls,1)});
